INSERT INTO `bt_chat_reply_theme` VALUES (1313121713955807232,'经典主题','jingdianzhuti',-1,'\r\n/**\r\n * MD 默认主题（经典主题）\r\n * 按 Alt/Option + Shift + F 可格式化\r\n * 如需使用主题色，请使用 #009874 代替颜色值\r\n */\r\n\r\n/* ==================== 一级标题 ==================== */\r\nh1 {\r\n  display: table;\r\n  padding: 0 1em;\r\n  border-bottom: 2px solid #009874;\r\n  margin: 2em auto 1em;\r\n  color: hsl(var(--foreground));\r\n  font-size: 16.8px;\r\n  font-weight: bold;\r\n  text-align: center;\r\n}\r\n\r\n/* ==================== 二级标题 ==================== */\r\nh2 {\r\n  display: table;\r\n  padding: 0 0.2em;\r\n  margin: 4em auto 2em;\r\n  color: #fff;\r\n  background: #009874;\r\n  font-size: 16.8px;\r\n  font-weight: bold;\r\n  text-align: center;\r\n}\r\n\r\n/* ==================== 三级标题 ==================== */\r\nh3 {\r\n  padding-left: 8px;\r\n  border-left: 3px solid #009874;\r\n  margin: 2em 8px 0.75em 0;\r\n  color: hsl(var(--foreground));\r\n  font-size: 15.400000000000002px;\r\n  font-weight: bold;\r\n  line-height: 1.2;\r\n}\r\n\r\n/* ==================== 四级标题 ==================== */\r\nh4 {\r\n  margin: 2em 8px 0.5em;\r\n  color: #009874;\r\n  font-size: 14px;\r\n  font-weight: bold;\r\n}\r\n\r\n/* ==================== 五级标题 ==================== */\r\nh5 {\r\n  margin: 1.5em 8px 0.5em;\r\n  color: #009874;\r\n  font-size: 14px;\r\n  font-weight: bold;\r\n}\r\n\r\n/* ==================== 六级标题 ==================== */\r\nh6 {\r\n  margin: 1.5em 8px 0.5em;\r\n  font-size: 14px;\r\n  color: #009874;\r\n}\r\n\r\n/* ==================== 段落 ==================== */\r\np {\r\n  margin: 1.5em 8px;\r\n  letter-spacing: 0.1em;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\n/* ==================== 引用块 ==================== */\r\nblockquote {\r\n  font-style: normal;\r\n  padding: 1em;\r\n  border-left: 4px solid #009874;\r\n  border-radius: 6px;\r\n  color: hsl(var(--foreground));\r\n  background: var(--blockquote-background);\r\n  margin-bottom: 1em;\r\n}\r\n\r\nblockquote > p {\r\n  display: block;\r\n  font-size: 1em;\r\n  letter-spacing: 0.1em;\r\n  color: hsl(var(--foreground));\r\n  margin: 0;\r\n}\r\n\r\n/* ==================== GFM 警告块 ==================== */\r\n.alert-title-note,\r\n.alert-title-tip,\r\n.alert-title-info,\r\n.alert-title-important,\r\n.alert-title-warning,\r\n.alert-title-caution {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.5em;\r\n  margin-bottom: 0.5em;\r\n}\r\n\r\n.alert-title-note {\r\n  color: #478be6;\r\n}\r\n\r\n.alert-title-tip {\r\n  color: #57ab5a;\r\n}\r\n\r\n.alert-title-info {\r\n  color: #93c5fd;\r\n}\r\n\r\n.alert-title-important {\r\n  color: #986ee2;\r\n}\r\n\r\n.alert-title-warning {\r\n  color: #c69026;\r\n}\r\n\r\n.alert-title-caution {\r\n  color: #e5534b;\r\n}\r\n\r\n/* GFM Alert SVG 图标颜色 */\r\n.alert-icon-note {\r\n  fill: #478be6;\r\n}\r\n\r\n.alert-icon-tip {\r\n  fill: #57ab5a;\r\n}\r\n\r\n.alert-icon-info {\r\n  fill: #93c5fd;\r\n}\r\n\r\n.alert-icon-important {\r\n  fill: #986ee2;\r\n}\r\n\r\n.alert-icon-warning {\r\n  fill: #c69026;\r\n}\r\n\r\n.alert-icon-caution {\r\n  fill: #e5534b;\r\n}\r\n\r\n/* ==================== 代码块 ==================== */\r\npre.code__pre,\r\n.hljs.code__pre {\r\n  font-size: 90%;\r\n  overflow-x: auto;\r\n  border-radius: 8px;\r\n  padding: 0 !important;\r\n  line-height: 1.5;\r\n  margin: 10px 8px;\r\n}\r\n\r\n/* ==================== 图片 ==================== */\r\nimg {\r\n  display: block;\r\n  max-width: 100%;\r\n  margin: 0.1em auto 0.5em;\r\n  border-radius: 4px;\r\n}\r\n\r\n/* ==================== 列表 ==================== */\r\nol {\r\n  padding-left: 1em;\r\n  margin-left: 0;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\nul {\r\n  list-style: circle;\r\n  padding-left: 1em;\r\n  margin-left: 0;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\nli {\r\n  display: block;\r\n  margin: 0.2em 8px;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\n/* ==================== 脚注 ==================== */\r\n/* footnotes 在 buildFootnotes() 中渲染为 <p> 标签 */\r\np.footnotes {\r\n  margin: 0.5em 8px;\r\n  font-size: 80%;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\n/* ==================== 图表 ==================== */\r\nfigure {\r\n  margin: 1.5em 8px;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\nfigcaption,\r\n.md-figcaption {\r\n  text-align: center;\r\n  color: #888;\r\n  font-size: 0.8em;\r\n}\r\n\r\n/* ==================== 分隔线 ==================== */\r\nhr {\r\n  border-style: solid;\r\n  border-width: 2px 0 0;\r\n  border-color: rgba(0, 0, 0, 0.1);\r\n  -webkit-transform-origin: 0 0;\r\n  -webkit-transform: scale(1, 0.5);\r\n  transform-origin: 0 0;\r\n  transform: scale(1, 0.5);\r\n  height: 0.4em;\r\n  margin: 1.5em 0;\r\n}\r\n\r\n/* ==================== 行内代码 ==================== */\r\ncode {\r\n  font-size: 90%;\r\n  color: #d14;\r\n  background: rgba(27, 31, 35, 0.05);\r\n  padding: 3px 5px;\r\n  border-radius: 4px;\r\n}\r\n\r\n/* 代码块内的 code 标签需要特殊处理（覆盖行内 code 样式） */\r\npre.code__pre > code,\r\n.hljs.code__pre > code {\r\n  display: -webkit-box;\r\n  padding: 0.5em 1em 1em;\r\n  overflow-x: auto;\r\n  text-indent: 0;\r\n  color: inherit;\r\n  background: none;\r\n  white-space: nowrap;\r\n  margin: 0;\r\n}\r\n\r\n/* ==================== 强调 ==================== */\r\nem {\r\n  font-style: italic;\r\n  font-size: inherit;\r\n}\r\n\r\n/* ==================== 链接 ==================== */\r\na {\r\n  color: #576b95;\r\n  text-decoration: none;\r\n}\r\n\r\n/* ==================== 粗体 ==================== */\r\nstrong {\r\n  color: #009874;\r\n  font-weight: bold;\r\n  font-size: inherit;\r\n}\r\n\r\n/* ==================== 表格 ==================== */\r\ntable {\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\nthead {\r\n  font-weight: bold;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\nth {\r\n  border: 1px solid #dfdfdf;\r\n  padding: 0.25em 0.5em;\r\n  color: hsl(var(--foreground));\r\n  word-break: keep-all;\r\n  background: rgba(0, 0, 0, 0.05);\r\n}\r\n\r\ntd {\r\n  border: 1px solid #dfdfdf;\r\n  padding: 0.25em 0.5em;\r\n  color: hsl(var(--foreground));\r\n  word-break: keep-all;\r\n}\r\n\r\n/* ==================== KaTeX 公式 ==================== */\r\n.katex-inline {\r\n  max-width: 100%;\r\n  overflow-x: auto;\r\n}\r\n\r\n.katex-block {\r\n  max-width: 100%;\r\n  overflow-x: auto;\r\n  -webkit-overflow-scrolling: touch;\r\n  padding: 0.5em 0;\r\n  text-align: center;\r\n}\r\n\r\n/* ==================== 标记高亮 ==================== */\r\n.markup-highlight {\r\n  background-color: #009874;\r\n  padding: 2px 4px;\r\n  border-radius: 2px;\r\n  color: #fff;\r\n}\r\n\r\n.markup-underline {\r\n  text-decoration: underline;\r\n  text-decoration-color: #009874;\r\n}\r\n\r\n.markup-wavyline {\r\n  text-decoration: underline wavy;\r\n  text-decoration-color: #009874;\r\n  text-decoration-thickness: 2px;\r\n}\r\n\r\n/**\r\n * MD 简洁主题 (@okooo5km)\r\n * 简洁现代的设计风格\r\n */\r\n\r\n/* ==================== 标题样式 ==================== */\r\nh1 {\r\n  padding: 0.5em 1em;\r\n  font-size: 19.599999999999998px;\r\n  text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.05);\r\n}\r\n\r\nh2 {\r\n  padding: 0.3em 1.2em;\r\n  font-size: 18.2px;\r\n  border-radius: 8px 24px 8px 24px;\r\n  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.06);\r\n}\r\n\r\nh3 {\r\n  padding-left: 12px;\r\n  font-size: 16.8px;\r\n  border-radius: 6px;\r\n  line-height: 2.4em;\r\n  border-left: 4px solid #009874;\r\n  border-right: 1px solid rgba(0, 152, 116, 0.1);\r\n  border-bottom: 1px solid rgba(0, 152, 116, 0.1);\r\n  border-top: 1px solid rgba(0, 152, 116, 0.1);\r\n  background: rgba(0, 152, 116, 0.08);\r\n}\r\n\r\nh4 {\r\n  font-size: 15.400000000000002px;\r\n  border-radius: 6px;\r\n}\r\n\r\nh5 {\r\n  font-size: 14px;\r\n  border-radius: 6px;\r\n}\r\n\r\nh6 {\r\n  font-size: 14px;\r\n  border-radius: 6px;\r\n}\r\n\r\n/* ==================== 引用块 ==================== */\r\nblockquote {\r\n  font-style: italic;\r\n  padding: 1em 1em 1em 2em;\r\n  color: rgba(0, 0, 0, 0.6);\r\n  border-bottom: 0.2px solid rgba(0, 0, 0, 0.04);\r\n  border-top: 0.2px solid rgba(0, 0, 0, 0.04);\r\n  border-right: 0.2px solid rgba(0, 0, 0, 0.04);\r\n}\r\n\r\n/* GFM Alert 样式覆盖 */\r\n.markdown-alert-note,\r\n.markdown-alert-tip,\r\n.markdown-alert-info,\r\n.markdown-alert-important,\r\n.markdown-alert-warning,\r\n.markdown-alert-caution {\r\n  font-style: italic;\r\n}\r\n\r\n/* ==================== 代码块 ==================== */\r\npre.code__pre,\r\n.hljs.code__pre {\r\n  border: 1px solid rgba(0, 0, 0, 0.04);\r\n}\r\n\r\npre.code__pre > code,\r\n.hljs.code__pre > code {\r\n  font-family:\r\n    \'Fira Code\',\r\n    Menlo,\r\n    Operator Mono,\r\n    Consolas,\r\n    Monaco,\r\n    monospace;\r\n}\r\n\r\n/* ==================== 图片 ==================== */\r\nimg {\r\n  border-radius: 8px;\r\n  border: 1px solid rgba(0, 0, 0, 0.04);\r\n}\r\n\r\nfigcaption,\r\n.md-figcaption {\r\n  text-align: center;\r\n  color: #888;\r\n  font-size: 0.8em;\r\n}\r\n\r\n/* ==================== 列表 ==================== */\r\nol {\r\n  padding-left: 1.5em;\r\n}\r\n\r\nul {\r\n  list-style: none;\r\n  padding-left: 1.5em;\r\n}\r\n\r\nli {\r\n  margin: 0.5em 8px;\r\n}\r\n\r\n/* ==================== 分隔线 ==================== */\r\nhr {\r\n  height: 1px;\r\n  border: none;\r\n  margin: 2em 0;\r\n  background: linear-gradient(to right, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.1), rgba(0, 0, 0, 0));\r\n}\r\n\r\n/* ==================== 强调 ==================== */\r\nem {\r\n  font-style: italic;\r\n  font-size: inherit;\r\n}\r\n\r\n/* ==================== 链接 ==================== */\r\na {\r\n  color: #576b95;\r\n  text-decoration: none;\r\n}\r\n','00X',1,'2025-12-02 20:36:53',1,'2025-12-02 20:36:53',NULL,NULL),(1313127626821345280,'优雅主题','youyazhuti',-1,'/**\r\n * MD 优雅主题 (@brzhang)\r\n * 在默认主题基础上添加优雅的视觉效果\r\n */\r\n\r\n/* ==================== 标题样式 ==================== */\r\nh1 {\r\n  padding: 0.5em 1em;\r\n  border-bottom: 2px solid var(--md-primary-color);\r\n  font-size: calc(var(--md-font-size) * 1.4);\r\n  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.1);\r\n}\r\n\r\nh2 {\r\n  padding: 0.3em 1em;\r\n  border-radius: 8px;\r\n  font-size: calc(var(--md-font-size) * 1.3);\r\n  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\r\n}\r\n\r\nh3 {\r\n  padding-left: 12px;\r\n  font-size: calc(var(--md-font-size) * 1.2);\r\n  border-left: 4px solid var(--md-primary-color);\r\n  border-bottom: 1px dashed var(--md-primary-color);\r\n}\r\n\r\nh4 {\r\n  font-size: calc(var(--md-font-size) * 1.1);\r\n}\r\n\r\nh5 {\r\n  font-size: var(--md-font-size);\r\n}\r\n\r\nh6 {\r\n  font-size: var(--md-font-size);\r\n}\r\n\r\n/* ==================== 引用块 ==================== */\r\nblockquote {\r\n  font-style: italic;\r\n  padding: 1em 1em 1em 2em;\r\n  border-left: 4px solid var(--md-primary-color);\r\n  border-radius: 6px;\r\n  color: rgba(0, 0, 0, 0.6);\r\n  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);\r\n  margin-bottom: 1em;\r\n}\r\n\r\n.markdown-alert {\r\n  font-style: italic;\r\n}\r\n\r\n/* ==================== 代码块 ==================== */\r\npre.code__pre,\r\n.hljs.code__pre {\r\n  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.05);\r\n}\r\n\r\npre.code__pre > code,\r\n.hljs.code__pre > code {\r\n  font-family:\r\n    \'Fira Code\',\r\n    Menlo,\r\n    Operator Mono,\r\n    Consolas,\r\n    Monaco,\r\n    monospace;\r\n}\r\n\r\n/* ==================== 图片 ==================== */\r\nimg {\r\n  border-radius: 8px;\r\n  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);\r\n}\r\n\r\nfigcaption,\r\n.md-figcaption {\r\n  text-align: center;\r\n  color: #888;\r\n  font-size: 0.8em;\r\n}\r\n\r\n/* ==================== 列表 ==================== */\r\nol {\r\n  padding-left: 1.5em;\r\n}\r\n\r\nul {\r\n  list-style: none;\r\n  padding-left: 1.5em;\r\n}\r\n\r\nli {\r\n  margin: 0.5em 8px;\r\n}\r\n\r\n/* ==================== 分隔线 ==================== */\r\nhr {\r\n  height: 1px;\r\n  border: none;\r\n  margin: 2em 0;\r\n  background: linear-gradient(to right, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.1), rgba(0, 0, 0, 0));\r\n}\r\n\r\n/* ==================== 表格 ==================== */\r\ntable {\r\n  border-collapse: separate;\r\n  border-spacing: 0;\r\n  border-radius: 8px;\r\n  margin: 1em 8px;\r\n  color: hsl(var(--foreground));\r\n  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\r\n  overflow: hidden;\r\n}\r\n\r\nthead {\r\n  color: #fff;\r\n}\r\n\r\ntd {\r\n  padding: 0.5em 1em;\r\n}\r\n\r\n/* ==================== 强调 ==================== */\r\nem {\r\n  font-style: italic;\r\n  font-size: inherit;\r\n}\r\n\r\n/* ==================== 链接 ==================== */\r\na {\r\n  color: #576b95;\r\n  text-decoration: none;\r\n}\r\n','00X',1,'2025-12-02 21:00:22',1,'2025-12-02 21:00:22',NULL,NULL),(1313127678180597760,'简洁主题','jianjiezhuti',-1,'/**\r\n * MD 简洁主题 (@okooo5km)\r\n * 简洁现代的设计风格\r\n */\r\n\r\n/* ==================== 标题样式 ==================== */\r\nh1 {\r\n  padding: 0.5em 1em;\r\n  font-size: calc(var(--md-font-size) * 1.4);\r\n  text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.05);\r\n}\r\n\r\nh2 {\r\n  padding: 0.3em 1.2em;\r\n  font-size: calc(var(--md-font-size) * 1.3);\r\n  border-radius: 8px 24px 8px 24px;\r\n  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.06);\r\n}\r\n\r\nh3 {\r\n  padding-left: 12px;\r\n  font-size: calc(var(--md-font-size) * 1.2);\r\n  border-radius: 6px;\r\n  line-height: 2.4em;\r\n  border-left: 4px solid var(--md-primary-color);\r\n  border-right: 1px solid color-mix(in srgb, var(--md-primary-color) 10%, transparent);\r\n  border-bottom: 1px solid color-mix(in srgb, var(--md-primary-color) 10%, transparent);\r\n  border-top: 1px solid color-mix(in srgb, var(--md-primary-color) 10%, transparent);\r\n  background: color-mix(in srgb, var(--md-primary-color) 8%, transparent);\r\n}\r\n\r\nh4 {\r\n  font-size: calc(var(--md-font-size) * 1.1);\r\n  border-radius: 6px;\r\n}\r\n\r\nh5 {\r\n  font-size: var(--md-font-size);\r\n  border-radius: 6px;\r\n}\r\n\r\nh6 {\r\n  font-size: var(--md-font-size);\r\n  border-radius: 6px;\r\n}\r\n\r\n/* ==================== 引用块 ==================== */\r\nblockquote {\r\n  font-style: italic;\r\n  padding: 1em 1em 1em 2em;\r\n  color: rgba(0, 0, 0, 0.6);\r\n  border-bottom: 0.2px solid rgba(0, 0, 0, 0.04);\r\n  border-top: 0.2px solid rgba(0, 0, 0, 0.04);\r\n  border-right: 0.2px solid rgba(0, 0, 0, 0.04);\r\n}\r\n\r\n/* GFM Alert 样式覆盖 */\r\n.markdown-alert-note,\r\n.markdown-alert-tip,\r\n.markdown-alert-info,\r\n.markdown-alert-important,\r\n.markdown-alert-warning,\r\n.markdown-alert-caution {\r\n  font-style: italic;\r\n}\r\n\r\n/* ==================== 代码块 ==================== */\r\npre.code__pre,\r\n.hljs.code__pre {\r\n  border: 1px solid rgba(0, 0, 0, 0.04);\r\n}\r\n\r\npre.code__pre > code,\r\n.hljs.code__pre > code {\r\n  font-family:\r\n    \'Fira Code\',\r\n    Menlo,\r\n    Operator Mono,\r\n    Consolas,\r\n    Monaco,\r\n    monospace;\r\n}\r\n\r\n/* ==================== 图片 ==================== */\r\nimg {\r\n  border-radius: 8px;\r\n  border: 1px solid rgba(0, 0, 0, 0.04);\r\n}\r\n\r\nfigcaption,\r\n.md-figcaption {\r\n  text-align: center;\r\n  color: #888;\r\n  font-size: 0.8em;\r\n}\r\n\r\n/* ==================== 列表 ==================== */\r\nol {\r\n  padding-left: 1.5em;\r\n}\r\n\r\nul {\r\n  list-style: none;\r\n  padding-left: 1.5em;\r\n}\r\n\r\nli {\r\n  margin: 0.5em 8px;\r\n}\r\n\r\n/* ==================== 分隔线 ==================== */\r\nhr {\r\n  height: 1px;\r\n  border: none;\r\n  margin: 2em 0;\r\n  background: linear-gradient(to right, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.1), rgba(0, 0, 0, 0));\r\n}\r\n\r\n/* ==================== 强调 ==================== */\r\nem {\r\n  font-style: italic;\r\n  font-size: inherit;\r\n}\r\n\r\n/* ==================== 链接 ==================== */\r\na {\r\n  color: #576b95;\r\n  text-decoration: none;\r\n}\r\n','00X',1,'2025-12-02 21:00:35',1,'2025-12-02 21:00:35',NULL,NULL),(1317736932126183424,'简洁橘','jianjieju',-1,'/**\r\n * MD 主题导出\r\n * 导出时间: 2025/12/15 14:06:25\r\n * 说明: 该文件包含完整的主题样式，可直接使用\r\n */\r\n:root {\r\n--md-font-family: Optima-Regular, Optima, PingFangSC-light, PingFangTC-light, \'PingFang SC\', Cambria, Cochin, Georgia, Times, \'Times New Roman\', serif;\r\n  --md-font-size: 16px;\r\n  --md-primary-color: #FA5151;\r\n}\r\n\r\n/**\r\n * MD 默认主题（经典主题）\r\n * 按 Alt/Option + Shift + F 可格式化\r\n * 如需使用主题色，请使用 var(--md-primary-color) 代替颜色值\r\n */\r\n\r\n/* ==================== 一级标题 ==================== */\r\nh1 {\r\n  display: table;\r\n  padding: 0 1em;\r\n  border-bottom: 2px solid var(--md-primary-color);\r\n  margin: 2em auto 1em;\r\n  color: hsl(var(--foreground));\r\n  font-size: calc(var(--md-font-size) * 1.2);\r\n  font-weight: bold;\r\n  text-align: center;\r\n}\r\n\r\n/* ==================== 二级标题 ==================== */\r\nh2 {\r\n  display: table;\r\n  padding: 0 0.2em;\r\n  margin: 4em auto 2em;\r\n  color: #fff;\r\n  background: var(--md-primary-color);\r\n  font-size: calc(var(--md-font-size) * 1.2);\r\n  font-weight: bold;\r\n  text-align: center;\r\n}\r\n\r\n/* ==================== 三级标题 ==================== */\r\nh3 {\r\n  padding-left: 8px;\r\n  border-left: 3px solid var(--md-primary-color);\r\n  margin: 2em 8px 0.75em 0;\r\n  color: hsl(var(--foreground));\r\n  font-size: calc(var(--md-font-size) * 1.1);\r\n  font-weight: bold;\r\n  line-height: 1.2;\r\n}\r\n\r\n/* ==================== 四级标题 ==================== */\r\nh4 {\r\n  margin: 2em 8px 0.5em;\r\n  color: var(--md-primary-color);\r\n  font-size: calc(var(--md-font-size) * 1);\r\n  font-weight: bold;\r\n}\r\n\r\n/* ==================== 五级标题 ==================== */\r\nh5 {\r\n  margin: 1.5em 8px 0.5em;\r\n  color: var(--md-primary-color);\r\n  font-size: calc(var(--md-font-size) * 1);\r\n  font-weight: bold;\r\n}\r\n\r\n/* ==================== 六级标题 ==================== */\r\nh6 {\r\n  margin: 1.5em 8px 0.5em;\r\n  font-size: calc(var(--md-font-size) * 1);\r\n  color: var(--md-primary-color);\r\n}\r\n\r\n/* ==================== 段落 ==================== */\r\np {\r\n  margin: 1.5em 8px;\r\n  letter-spacing: 0.1em;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\n/* ==================== 引用块 ==================== */\r\nblockquote {\r\n  font-style: normal;\r\n  padding: 1em;\r\n  border-left: 4px solid var(--md-primary-color);\r\n  border-radius: 6px;\r\n  color: hsl(var(--foreground));\r\n  background: var(--blockquote-background);\r\n  margin-bottom: 1em;\r\n}\r\n\r\nblockquote > p {\r\n  display: block;\r\n  font-size: 1em;\r\n  letter-spacing: 0.1em;\r\n  color: hsl(var(--foreground));\r\n  margin: 0;\r\n}\r\n\r\n/* ==================== GFM 警告块 ==================== */\r\n.alert-title-note,\r\n.alert-title-tip,\r\n.alert-title-info,\r\n.alert-title-important,\r\n.alert-title-warning,\r\n.alert-title-caution {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.5em;\r\n  margin-bottom: 0.5em;\r\n}\r\n\r\n.alert-title-note {\r\n  color: #478be6;\r\n}\r\n\r\n.alert-title-tip {\r\n  color: #57ab5a;\r\n}\r\n\r\n.alert-title-info {\r\n  color: #93c5fd;\r\n}\r\n\r\n.alert-title-important {\r\n  color: #986ee2;\r\n}\r\n\r\n.alert-title-warning {\r\n  color: #c69026;\r\n}\r\n\r\n.alert-title-caution {\r\n  color: #e5534b;\r\n}\r\n\r\n/* GFM Alert SVG 图标颜色 */\r\n.alert-icon-note {\r\n  fill: #478be6;\r\n}\r\n\r\n.alert-icon-tip {\r\n  fill: #57ab5a;\r\n}\r\n\r\n.alert-icon-info {\r\n  fill: #93c5fd;\r\n}\r\n\r\n.alert-icon-important {\r\n  fill: #986ee2;\r\n}\r\n\r\n.alert-icon-warning {\r\n  fill: #c69026;\r\n}\r\n\r\n.alert-icon-caution {\r\n  fill: #e5534b;\r\n}\r\n\r\n/* ==================== 代码块 ==================== */\r\npre.code__pre,\r\n.hljs.code__pre {\r\n  font-size: 90%;\r\n  overflow-x: auto;\r\n  border-radius: 8px;\r\n  padding: 0 !important;\r\n  line-height: 1.5;\r\n  margin: 10px 8px;\r\n}\r\n\r\n/* ==================== 图片 ==================== */\r\nimg {\r\n  display: block;\r\n  max-width: 100%;\r\n  margin: 0.1em auto 0.5em;\r\n  border-radius: 4px;\r\n}\r\n\r\n/* ==================== 列表 ==================== */\r\nol {\r\n  padding-left: 1em;\r\n  margin-left: 0;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\nul {\r\n  list-style: circle;\r\n  padding-left: 1em;\r\n  margin-left: 0;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\nli {\r\n  display: block;\r\n  margin: 0.2em 8px;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\n/* ==================== 脚注 ==================== */\r\n/* footnotes 在 buildFootnotes() 中渲染为 <p> 标签 */\r\np.footnotes {\r\n  margin: 0.5em 8px;\r\n  font-size: 80%;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\n/* ==================== 图表 ==================== */\r\nfigure {\r\n  margin: 1.5em 8px;\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\nfigcaption,\r\n.md-figcaption {\r\n  text-align: center;\r\n  color: #888;\r\n  font-size: 0.8em;\r\n}\r\n\r\n/* ==================== 分隔线 ==================== */\r\nhr {\r\n  border-style: solid;\r\n  border-width: 2px 0 0;\r\n  border-color: rgba(0, 0, 0, 0.1);\r\n  -webkit-transform-origin: 0 0;\r\n  -webkit-transform: scale(1, 0.5);\r\n  transform-origin: 0 0;\r\n  transform: scale(1, 0.5);\r\n  height: 0.4em;\r\n  margin: 1.5em 0;\r\n}\r\n\r\n/* ==================== 行内代码 ==================== */\r\ncode {\r\n  font-size: 90%;\r\n  color: #d14;\r\n  background: rgba(27, 31, 35, 0.05);\r\n  padding: 3px 5px;\r\n  border-radius: 4px;\r\n}\r\n\r\n/* 代码块内的 code 标签需要特殊处理（覆盖行内 code 样式） */\r\npre.code__pre > code,\r\n.hljs.code__pre > code {\r\n  display: -webkit-box;\r\n  padding: 0.5em 1em 1em;\r\n  overflow-x: auto;\r\n  text-indent: 0;\r\n  color: inherit;\r\n  background: none;\r\n  white-space: nowrap;\r\n  margin: 0;\r\n}\r\n\r\n/* ==================== 强调 ==================== */\r\nem {\r\n  font-style: italic;\r\n  font-size: inherit;\r\n}\r\n\r\n/* ==================== 链接 ==================== */\r\na {\r\n  color: #576b95;\r\n  text-decoration: none;\r\n}\r\n\r\n/* ==================== 粗体 ==================== */\r\nstrong {\r\n  color: var(--md-primary-color);\r\n  font-weight: bold;\r\n  font-size: inherit;\r\n}\r\n\r\n/* ==================== 表格 ==================== */\r\ntable {\r\n  color: hsl(var(--foreground));\r\n}\r\n\r\nthead {\r\n  font-weight: bold;\r\