n}\r\n\r\nth {\r\n  border: 1px solid #dfdfdf;\r\n  padding: 0.25em 0.5em;\r\n  color: hsl(var(--foreground));\r\n  word-break: keep-all;\r\n  background: rgba(0, 0, 0, 0.05);\r\n}\r\n\r\ntd {\r\n  border: 1px solid #dfdfdf;\r\n  padding: 0.25em 0.5em;\r\n  color: hsl(var(--foreground));\r\n  word-break: keep-all;\r\n}\r\n\r\n/* ==================== KaTeX 公式 ==================== */\r\n.katex-inline {\r\n  max-width: 100%;\r\n  overflow-x: auto;\r\n}\r\n\r\n.katex-block {\r\n  max-width: 100%;\r\n  overflow-x: auto;\r\n  -webkit-overflow-scrolling: touch;\r\n  padding: 0.5em 0;\r\n  text-align: center;\r\n}\r\n\r\n/* ==================== 标记高亮 ==================== */\r\n.markup-highlight {\r\n  background-color: var(--md-primary-color);\r\n  padding: 2px 4px;\r\n  border-radius: 2px;\r\n  color: #fff;\r\n}\r\n\r\n.markup-underline {\r\n  text-decoration: underline;\r\n  text-decoration-color: var(--md-primary-color);\r\n}\r\n\r\n.markup-wavyline {\r\n  text-decoration: underline wavy;\r\n  text-decoration-color: var(--md-primary-color);\r\n  text-decoration-thickness: 2px;\r\n}\r\n\r\n\r\n/**\r\n * MD 优雅主题 (@brzhang)\r\n * 在默认主题基础上添加优雅的视觉效果\r\n */\r\n\r\n/* ==================== 标题样式 ==================== */\r\nh1 {\r\n  padding: 0.5em 1em;\r\n  border-bottom: 2px solid var(--md-primary-color);\r\n  font-size: calc(var(--md-font-size) * 1.4);\r\n  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.1);\r\n}\r\n\r\nh2 {\r\n  padding: 0.3em 1em;\r\n  border-radius: 8px;\r\n  font-size: calc(var(--md-font-size) * 1.3);\r\n  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\r\n}\r\n\r\nh3 {\r\n  padding-left: 12px;\r\n  font-size: calc(var(--md-font-size) * 1.2);\r\n  border-left: 4px solid var(--md-primary-color);\r\n  border-bottom: 1px dashed var(--md-primary-color);\r\n}\r\n\r\nh4 {\r\n  font-size: calc(var(--md-font-size) * 1.1);\r\n}\r\n\r\nh5 {\r\n  font-size: var(--md-font-size);\r\n}\r\n\r\nh6 {\r\n  font-size: var(--md-font-size);\r\n}\r\n\r\n/* ==================== 引用块 ==================== */\r\nblockquote {\r\n  font-style: italic;\r\n  padding: 1em 1em 1em 2em;\r\n  border-left: 4px solid var(--md-primary-color);\r\n  border-radius: 6px;\r\n  color: rgba(0, 0, 0, 0.6);\r\n  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);\r\n  margin-bottom: 1em;\r\n}\r\n\r\n.markdown-alert {\r\n  font-style: italic;\r\n}\r\n\r\n/* ==================== 代码块 ==================== */\r\npre.code__pre,\r\n.hljs.code__pre {\r\n  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.05);\r\n}\r\n\r\npre.code__pre > code,\r\n.hljs.code__pre > code {\r\n  font-family:\r\n    \'Fira Code\',\r\n    Menlo,\r\n    Operator Mono,\r\n    Consolas,\r\n    Monaco,\r\n    monospace;\r\n}\r\n\r\n/* ==================== 图片 ==================== */\r\nimg {\r\n  border-radius: 8px;\r\n  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);\r\n}\r\n\r\nfigcaption,\r\n.md-figcaption {\r\n  text-align: center;\r\n  color: #888;\r\n  font-size: 0.8em;\r\n}\r\n\r\n/* ==================== 列表 ==================== */\r\nol {\r\n  padding-left: 1.5em;\r\n}\r\n\r\nul {\r\n  list-style: none;\r\n  padding-left: 1.5em;\r\n}\r\n\r\nli {\r\n  margin: 0.5em 8px;\r\n}\r\n\r\n/* ==================== 分隔线 ==================== */\r\nhr {\r\n  height: 1px;\r\n  border: none;\r\n  margin: 2em 0;\r\n  background: linear-gradient(to right, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.1), rgba(0, 0, 0, 0));\r\n}\r\n\r\n/* ==================== 表格 ==================== */\r\ntable {\r\n  border-collapse: separate;\r\n  border-spacing: 0;\r\n  border-radius: 8px;\r\n  margin: 1em 8px;\r\n  color: hsl(var(--foreground));\r\n  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);\r\n  overflow: hidden;\r\n}\r\n\r\nthead {\r\n  color: #fff;\r\n}\r\n\r\ntd {\r\n  padding: 0.5em 1em;\r\n}\r\n\r\n/* ==================== 强调 ==================== */\r\nem {\r\n  font-style: italic;\r\n  font-size: inherit;\r\n}\r\n\r\n/* ==================== 链接 ==================== */\r\na {\r\n  color: #576b95;\r\n  text-decoration: none;\r\n}\r\n','00A',1,'2025-12-15 14:16:34',1,'2025-12-15 14:16:34',NULL,NULL);
