--
-- Table structure for table `bt_chat_theme`
--


CREATE TABLE `bt_chat_theme` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `theme_id` bigint(20) NOT NULL COMMENT '主题ID',
  `theme_name` varchar(64) NOT NULL COMMENT '主题名称',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户ID',
  `bot_id` bigint(20) NOT NULL COMMENT '智能应用ID',
  `theme_scope` varchar(64) NOT NULL COMMENT '主题级别（app:应用级别，tenant:租户级别，platform：平台级别）',
  `theme_json` text COMMENT '主题JSON配置',
  `theme_icon` mediumtext COMMENT '主题图片',
  `theme_tag` varchar(255) DEFAULT NULL COMMENT '主题标签',
  `is_using` varchar(1) NOT NULL COMMENT '是否使用中（T/F）',
  `status_cd` varchar(10) NOT NULL COMMENT '状态（00A:有效, 00X:无效）',
  `creator_id` bigint(20) DEFAULT NULL COMMENT '创建人ID',
  `created_time` datetime DEFAULT NULL COMMENT '创建时间',
  `updator_id` bigint(20) DEFAULT NULL COMMENT '更新人ID',
  `updated_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `reply_theme_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`,`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='对话主题表';
/*!40101 SET character_set_client = @saved_cs_client */;

