--
-- Table structure for table `bt_dc_doc_content_history`
--


CREATE TABLE `bt_dc_doc_content_history` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `document_id` varchar(64) NOT NULL COMMENT '文档唯一标识',
  `content` text NOT NULL COMMENT '文档内容json',
  `revision` int(11) NOT NULL DEFAULT '0' COMMENT '版本号',
  `created_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `status_cd` varchar(10) NOT NULL DEFAULT '00A' COMMENT '状态：00A-正常，00X-删除',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户ID',
  `creator_id` bigint(20) DEFAULT NULL COMMENT '创建人id',
  PRIMARY KEY (`id`),
  KEY `idx_doc_id_history` (`document_id`),
