--
-- Table structure for table `bt_document`
--


CREATE TABLE `bt_document` (
  `document_id` bigint(20) NOT NULL COMMENT '文档 ID',
  `knowledge_id` bigint(20) DEFAULT NULL COMMENT '知识库 ID',
  `file_id` bigint(20) DEFAULT NULL COMMENT '文件 ID',
  `data_from` varchar(4) DEFAULT NULL COMMENT '文档来源(10A: 上传, 10B: 网页爬取)',
  `doc_name` varchar(255) DEFAULT NULL COMMENT '文档名称',
  `parse_started_time` datetime DEFAULT NULL COMMENT '解析开始时间',
  `extract_started_time` datetime DEFAULT NULL COMMENT '要素提取开始时间',
  `process_completed_at` datetime DEFAULT NULL COMMENT '构建完成时间',
  `doc_status` varchar(4) DEFAULT NULL COMMENT '文档状态(10A: 未处理, 10B: 解析中, 10C: 要素抽取中, 10D: 构建完成, 10E: 构建失败)',
  `status_cd` varchar(4) DEFAULT NULL,
  `creator_id` bigint(20) DEFAULT NULL,
  `created_time` datetime DEFAULT NULL,
  `updator_id` bigint(20) DEFAULT NULL,
  `updated_time` datetime DEFAULT NULL,
  `error_message` longtext COMMENT '错误信息',
  `ext_system_id` bigint(20) DEFAULT NULL COMMENT '外系统 ID',
  `file_info_id` bigint(20) DEFAULT NULL COMMENT '文件信息 ID',
  `obj_id` bigint(20) DEFAULT NULL,
  `tenant_id` bigint(20) NOT NULL COMMENT '租户 ID',
  `document_type` varchar(50) DEFAULT NULL,
  `dc_document_id` varchar(64) DEFAULT NULL COMMENT '关联文档中心文档ID',
  `file_md5` varchar(32) DEFAULT NULL COMMENT '文件MD5校验值',
  `version_number` varchar(50) DEFAULT NULL COMMENT '版本号',
  `file_size` bigint(20) DEFAULT NULL COMMENT '文档文件大小（字节）',
  `last_sync_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后同步时间',
  `last_check_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后检查时间',
  `has_update` char(1) NOT NULL DEFAULT '0' COMMENT '是否有更新：0-无更新，1-有更新',
  `space_id` bigint(20) DEFAULT NULL COMMENT '空间id',
  PRIMARY KEY (`document_id`,`tenant_id`),
  KEY `idx_file_md5` (`file_md5`),
  KEY `idx_last_check_time` (`last_check_time`),
  KEY `idx_bt_document_space_id` (`space_id`),
  KEY `idx_bt_doc_tt_st_dcid` (`tenant_id`,`status_cd`,`dc_document_id`),
  KEY `idx_bt_doc_st_extsid` (`status_cd`,`ext_system_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='文档';
/*!40101 SET character_set_client = @saved_cs_client */;

