  `field_type` int(11) DEFAULT NULL COMMENT '聚合字段类型 1：评估器得分',
  `field_key` varchar(255) NOT NULL COMMENT '聚合字段唯一标识',
  `score` decimal(10,4) DEFAULT NULL COMMENT '聚合后的平均得分',
  `aggr_result` longtext COMMENT '详细聚合结果（JSON格式）',
  `version` bigint(20) NOT NULL COMMENT '版本号(用于乐观锁)',
  `status` int(11) NOT NULL COMMENT '计算状态 1:idle 2:calculating',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted_at` bigint(20) NOT NULL COMMENT '删除时间（时间戳，NULL或0表示未删除）',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='实验聚合结果表';
