INSERT INTO `bt_guidance_cfg` VALUES (1,'智能体开发','agent','data:image/png;base64,','data:image/png;base64,','选择合适的智能体类型，开始编排','可按照不同的业务场景需求选择包含三种不同方式，可根据业务场景，选择智能体搭建方式，并完成配置，快速搭建对话式智能体。',3,'2025-08-08 06:40:49','00A','2025-12-05 12:00:00',1,NULL,NULL,'beginner_guide',1),(2,'智能应用开发','bot','data:image/png;base64,','data:image/png;base64,','智能应用配置','基于配置的智能体进行管理，可配置指令、常见问题、推荐场景等功能，并支持自定义主题与调整功能相关设置，提供包含用户界面交互的完整对话窗口应用。',4,'2025-08-08 06:40:49','00A','2025-11-13 12:00:00',1,NULL,NULL,'beginner_guide',2),(3,'技能开发','assets','data:image/png;base64,','data:image/png;base64,','技能开发','技能是业务场景所需的能力单元，由平台统一配置和管理，供场景编排时灵活调用。',5,'2025-08-08 06:40:50','00A','2025-11-13 12:00:00',1,NULL,NULL,'beginner_guide',3);
INSERT INTO `bt_guidance_cfg` VALUES (4,'开放设置','api','data:image/png;base64,','data:image/png;base64,','选择并设置开放模式','智能体和智能应用开发完成后通过服务、菜单集成或者图标副驾集成方式进行集成内容获取。',6,'2025-08-08 06:40:51','00A','2025-11-13 12:00:00',1,NULL,NULL,'beginner_guide',4),(5,'准备工作','prepare',NULL,'data:image/png;base64,','开发前准备','开发前要先进行项目确认，明确当前所处项目（因不同项目数据完全隔离），之后可在设置、管理菜单中更改项目配置、管理项目成员并设置权限、查看项目数据。',1,'2025-11-13 12:00:00','00A','2025-11-13 12:00:00',1,NULL,NULL,'beginner_guide',5),(6,'准备工作-项目创建','prepareCreateTenant',NULL,NULL,'项目创建','系统可自动为您生成项目，您也可以申请加入其他已有的项目。',2,'2025-11-13 12:00:00','00A','2025-11-13 12:00:00',1,NULL,NULL,'beginner_guide',5),(101,'开发','devIntro',NULL,NULL,NULL,'提供创建、配置、调试、部署等能功能',1,'2025-11-11 20:00:00','00A','2025-11-11 20:00:00',1,NULL,NULL,'bote_navigation_guide_step',101),(102,'应用','appIntro',NULL,NULL,NULL,'海量智能应用，把万能工具箱装进口袋',2,'2025-11-11 20:00:00','00A','2025-11-11 20:00:00',1,NULL,NULL,'bote_navigation_guide_step',102),(103,'广场','groundIntro',NULL,NULL,NULL,'多款插件、工具随取随用',3,'2025-11-11 20:00:00','00A','2025-11-11 20:00:00',1,NULL,NULL,'bote_navigation_guide_step',103),(104,'创建','createIntro',NULL,NULL,NULL,'快速创建智能体和智能应用',4,'2025-11-11 20:00:00','00A','2025-11-11 20:00:00',1,NULL,NULL,'bote_side_guide_step',104),(105,'BOT','botIntro',NULL,NULL,NULL,'专注于智能体开发和管理',5,'2025-11-11 20:00:00','00A','2025-11-11 20:00:00',1,NULL,NULL,'bote_side_guide_step',105),(106,'资源','resourceIntro',NULL,NULL,NULL,'知识、模型、技能、提示词等资源管理',6,'2025-11-11 20:00:00','00A','2025-11-11 20:00:00',1,NULL,NULL,'bote_side_guide_step',106),(107,'设置','settingIntro',NULL,NULL,NULL,'欢迎页、人设、数据、网关、记录',7,'2025-11-11 20:00:00','00A','2025-11-11 20:00:00',1,NULL,NULL,'bote_side_guide_step',107),(108,'管理','manageIntro',NULL,NULL,NULL,'用户管理、资源发布、智能体管理',8,'2025-11-11 20:00:00','00A','2025-11-11 20:00:00',1,NULL,NULL,'bote_side_guide_step',108),(109,'新手指引','guideIntro',NULL,NULL,NULL,'你想了解的平台信息、操作方式，在这里都可以找到哦！',9,'2025-11-11 20:00:00','00A','2025-11-11 20:00:00',1,NULL,NULL,'bote_beginner_guide_step',109);
