  `priv_id` bigint(20) NOT NULL COMMENT '权限 ID',
  `priv_type` varchar(12) NOT NULL COMMENT '权限类型',
  `priv_code` varchar(128) NOT NULL COMMENT '权限编码',
  `priv_name` varchar(128) DEFAULT NULL COMMENT '权限名称',
  `priv_url` varchar(250) DEFAULT NULL,
  `catalog_item_id` bigint(20) DEFAULT NULL COMMENT '目录 ID',
  `created_time` datetime NOT NULL,
  `status_cd` varchar(4) NOT NULL,
  `updated_time` datetime DEFAULT NULL,
  `creator_id` bigint(20) DEFAULT NULL,
  `updator_id` bigint(20) DEFAULT NULL,
  `remark` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`priv_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='权限';
