--
-- Table structure for table `bt_skill_flow_param`
--


CREATE TABLE `bt_skill_flow_param` (
  `param_id` bigint(20) NOT NULL COMMENT '参数 ID',
  `flow_id` bigint(20) DEFAULT NULL COMMENT '工作流 ID',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户 ID',
  `variable_json` longtext COMMENT '变量',
  `request_json` longtext COMMENT '入参',
  `response_json` longtext COMMENT '出参',
  `created_time` datetime DEFAULT NULL,
  `status_cd` varchar(4) DEFAULT NULL,
  `updated_time` datetime DEFAULT NULL,
  `creator_id` bigint(20) DEFAULT NULL,
  `updator_id` bigint(20) DEFAULT NULL,
  `remark` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`param_id`,`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='工作流参数';
/*!40101 SET character_set_client = @saved_cs_client */;

