--
-- Table structure for table `bt_skill_function`
--


CREATE TABLE `bt_skill_function` (
  `func_id` bigint(20) NOT NULL COMMENT '函数 ID',
  `func_code` varchar(50) DEFAULT NULL COMMENT '函数编码',
  `func_name` varchar(100) DEFAULT NULL COMMENT '函数名称',
  `script_json` longtext COMMENT '函数内容',
  `req_json` longtext COMMENT '入参',
  `resp_json` longtext COMMENT '出参',
  `created_time` datetime NOT NULL,
  `status_cd` varchar(4) NOT NULL,
  `updated_time` datetime DEFAULT NULL,
  `creator_id` bigint(20) DEFAULT NULL,
  `updator_id` bigint(20) DEFAULT NULL,
  `remark` varchar(200) DEFAULT NULL,
  `catalog_item_id` bigint(20) DEFAULT NULL COMMENT '目录 ID',
  `func_type` varchar(18) DEFAULT NULL COMMENT '函数类型(groovy, python3)',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户 ID',
  `py_package` varchar(1000) DEFAULT NULL COMMENT 'python包列表',
  PRIMARY KEY (`func_id`,`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='服务函数';
