  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `bot_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='新增表记录启用模型';
