INSERT INTO `bt_api` VALUES (1001,'开启对话','发起一次对话，支持添加上下文和流式响应','/bote/chat/completions','POST',NULL,NULL,'{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"租户ID，可选\",\"name\":\"tenantId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"adcb3439-2fde-4e56-b9d7-9fa27f5deb67\",\"parentKey\":-1},{\"description\":\"机器人ID\",\"name\":\"botId\",\"type\":\"integer\",\"require\":true,\"value\":\"\",\"key\":\"fc440006-34fa-4713-88bc-645febe57d40\",\"parentKey\":-1},{\"description\":\"机器人ID列表\",\"name\":\"botIds\",\"type\":\"array\",\"require\":false,\"value\":\"\",\"key\":\"041e3342-4d1a-a4d4-8cf6-b9198456abe3\",\"parentKey\":-1},{\"description\":\"客户端 ID，可选\",\"name\":\"clientId\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"e8c2024a-11a9-81d8-0d42-ba67ad65731b\",\"parentKey\":-1},{\"description\":\"会话 ID，可选\",\"name\":\"sessionId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"52309665-aa68-7cd5-bf62-edf0c4d8c706\",\"parentKey\":-1},{\"description\":\"当前上下文 ID, 可选\",\"name\":\"contextId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"a50c0627-6db0-b61e-b00d-10aa27af8bcd\",\"parentKey\":-1},{\"description\":\"当前场景 ID\",\"name\":\"sceneId\",\"type\":\"integer\",\"require\":true,\"value\":\"\",\"key\":\"d6957081-2135-28e5-b883-c5ee90162d75\",\"parentKey\":-1},{\"description\":\"当前场景名称\",\"name\":\"sceneName\",\"type\":\"string\",\"require\":true,\"value\":\"\",\"key\":\"47bf2ea2-fb38-5b52-cba6-3d7db7332454\",\"parentKey\":-1},{\"description\":\"上一个场景 ID, 退出场景时使用\",\"name\":\"lastSceneId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"47bf2ea2-fb38-5b52-cba6-3d7db7332455\",\"parentKey\":-1},{\"description\":\"上一个上下文 ID, 退出场景时使用\",\"name\":\"lastContextId\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"0c74d1c4-7c00-a377-4c14-5c14d55fdd90\",\"parentKey\":-1},{\"description\":\"消息\",\"name\":\"message\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"fea2186e-365f-43eb-9d97-d8a42b755425\",\"parentKey\":-1,\"children\":[{\"description\":\"消息类型\",\"name\":\"type\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"8578933e-2004-c7a3-dd96-36b26cecc589\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"},{\"description\":\"消息角色\",\"name\":\"role\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"8d2c9f97-150e-b260-6b9f-01b03322975b\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"},{\"description\":\"消息内容\",\"name\":\"content\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"5b26ea1c-1410-bb11-91ff-52c31a92c928\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"},{\"description\":\"文件 ID 列表\",\"name\":\"fileIds\",\"type\":\"array\",\"require\":false,\"value\":\"\",\"key\":\"77d3b639-5071-5c49-f006-5f63e872b2d8\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"},{\"description\":\"参数\",\"name\":\"params\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"a4dc204a-b96d-2d9d-cc44-c5854a0dc2ff\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"},{\"description\":\"关联消息 ID，可选\",\"name\":\"refId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"74f27918-d4bf-701c-524e-367640881552\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"},{\"description\":\"工具调用 ID\",\"name\":\"toolCallId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"46b564e8-6965-40bc-d1f9-60c6b5a51579\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"}]},{\"description\":\"上下文参数\",\"name\":\"contextParams\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"9362c79f-a3b7-d7a9-db0e-2a5617d722e9\",\"parentKey\":-1},{\"description\":\"计划参数\",\"name\":\"planParams\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"9362c79f-a3b7-d7a9-db0e-2a5617d72219\",\"parentKey\":-1,\"children\":[{\"description\":\"标识是否通过应用的规划智策略生成计划\",\"name\":\"planable\",\"type\":\"boolean\",\"require\":false,\"value\":\"\",\"key\":\"8578933e-2004-c7a3-dd96-36b26cecc511\",\"parentKey\":\"9362c79f-a3b7-d7a9-db0e-2a5617d72219\"},{\"description\":\"通过应用的规划智策略生成计划，初始化的智能体列表\",\"name\":\"busiInfos\",\"type\":\"array\",\"require\":false,\"value\":\"\",\"key\":\"8578933e-2004-c7a3-dd96-36b26cecc512\",\"parentKey\":\"9362c79f-a3b7-d7a9-db0e-2a5617d72219\",\"children\":[{\"description\":\"智能体ID\",\"name\":\"agentId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"8578933e-2004-c7a3-dd96-36b26cecc531\",\"parentKey\":\"8578933e-2004-c7a3-dd96-36b26cecc512\"},{\"description\":\"智能体名称\",\"name\":\"agentName\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"8578933e-2004-c7a3-dd96-36b26cecc532\",\"parentKey\":\"8578933e-2004-c7a3-dd96-36b26cecc512\"},{\"description\":\"智能体文本输入\",\"name\":\"agentRequest\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"8578933e-2004-c7a3-dd96-36b26cecc533\",\"parentKey\":\"8578933e-2004-c7a3-dd96-36b26cecc512\"},{\"description\":\"智能体入参\",\"name\":\"agentParam\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"8578933e-2004-c7a3-dd96-36b26cecc534\",\"parentKey\":\"8578933e-2004-c7a3-dd96-36b26cecc512\"}]}]},{\"description\":\"是否启用联网搜索\",\"name\":\"webSearchEnabled\",\"type\":\"boolean\",\"require\":false,\"value\":\"\",\"key\":\"9362c79f-a3b7-d7a9-db0e-2a5617d72229\",\"parentKey\":-1}]}','{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"事件ID\",\"name\":\"id\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"adcb3439-2fde-4e56-b9d7-9fa27f5deb67\",\"parentKey\":-1},{\"description\":\"事件名称\",\"name\":\"envent\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"fc440006-34fa-4713-88bc-645febe57d40\",\"parentKey\":-1},{\"description\":\"事件数据\",\"name\":\"data\",\"type\":\"any\",\"require\":false,\"value\":\"\",\"key\":\"fea2186e-365f-43eb-9d97-d8a42b755425\",\"parentKey\":-1}]}','{\r\n	\"input\": \"curl --location --request POST \'http:\\/\\/10.10.176.135:9500\\/bote\\/api\\/bote\\/chat\\/completions\' \\\\\\r\\n--header \'Authorization: Bearer abcd***1234\' \\\\\\r\\n--header \'Content-Type: application\\/json\' \\\\\\r\\n--header \'Accept: *\\/*\' \\\\\\r\\n--header \'Connection: keep-alive\' \\\\\\r\\n--data-raw \'{\\r\\n    \\\"botId\\\": \\\"1224246182091034624\\\",\\r\\n    \\\"sessionId\\\": \\\"1224247868020887552\\\",\\r\\n    \\\"message\\\": {\\r\\n        \\\"role\\\": \\\"user\\\",\\r\\n        \\\"content\\\": \\\"中国有几个省\\\",\\r\\n        \\\"type\\\": \\\"input\\\"\\r\\n    },\\r\\n    \\\"sceneId\\\": \\\"1224246482281566208\\\",\\r\\n    \\\"sceneName\\\": \\\"简单对话\\\",\\r\\n    \\\"tenantId\\\": \\\"0\\\",\\r\\n    \\\"clientId\\\": \\\"a46997d4-4af9-4494-828f-d8c65e4b0fff\\\",\\r\\n    \\\"webSearchEnabled\\\": false\\r\\n}\'\",\r\n	\"output\": \"Content-Type: text\\/event-stream\\r\\nTransfer-Encoding: chunked\\r\\n\\r\\nevent:contextId\\r\\ndata:06649fd5-55ef-42bd-af32-3a843d6c183c\\r\\n\\r\\nevent:scene\\r\\ndata:{\\\"sceneName\\\":\\\"复杂对话\\\",\\\"sceneId\\\":\\\"1224249955618263040\\\"}\\r\\n\\r\\nid:1224252173260034048\\r\\nevent:text\\r\\ndata:\\\"中国的省级行政区共有34个，包括23个省，5个自治区，4个直辖市，3个特别行政区。\\\"\\r\\n\\r\\nid:1224252173260034048\\r\\nevent:done\\r\\ndata:[DONE]\"\r\n}',2001,'2025-02-26 18:14:50','00A','2025-02-26 18:14:50',1,1,NULL,'{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"Cookie 请求头\",\"name\":\"Cookie\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"axef8ad2a-csa1-48a8-bss1-ba5155acg4da\",\"parentKey\":-1},{\"description\":\"API 密钥, 值为 \\\"Bearer 密钥\\\"\",\"name\":\"Authorization\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"245e2b31-bff6-2c1a-ec7c-3cf340480a98\",\"parentKey\":-1}]}','对话接口用于聊天窗口与后端的交互，主要用于博特平台前端，如果业务系统需要使用自己的聊天窗口，也可通过此接口与博特平台后端交付。\r\n\r\n\r\n\r\n## 接口鉴权\r\n\r\n两种方式:\r\n\r\n\r\n\r\n* 使用 session 鉴权: 传递 `Cookie` 请求头，里面要包含 session 的 cookie（一般名为 `BOTE_SESSION`）\r\n\r\n  * 适用于从业务系统前端触发的调用，此时业务系统后端可以从请求中获取到 cookie, 然后转发给博特平台后端\r\n\r\n  * 博特平台不同环境使用的 session cookie 名称不同，为方便兼容所有环境，建议直接透传所有 cookie\r\n\r\n  * 示例: `Cookie: BOTE_SESSION=xxx`\r\n\r\n* API 密钥: 传递 `Authorization` 请求头，值为 \"Bearer 密钥\"\r\n\r\n  * 密钥在平台的【设置 - API 开放 - 鉴权】中申请\r\n\r\n  * 不依赖业务系统前端的 cookie, 适用于业务系统后端异步或者在定时任务中调用\r\n\r\n  * 示例: `Authorization: Bearer xxx`\r\n\r\n\r\n\r\n## 接口地址\r\n\r\n\r\n\r\n* 请求方法: POST\r\n\r\n* 请求地址: `/api/bote/chat/completions`（前面加上环境地址，比如生产环境完整地址为 `http://10.10.176.135:9500/bote/api/bote/chat/completions`）\r\n\r\n\r\n\r\n## 接口入参\r\n\r\n```json\r\n\r\n{\r\n\r\n  // 租户 ID，可选，也可通过请求头 Tenant-Id 或 URL 参数 tenantId 传递。使用 API 密钥鉴权方式时可不传（API 密钥与租户是绑定的，系统能自动查出来）\r\n\r\n  \"tenantId\": \"1\",\r\n\r\n  // 当前机器人 ID, 必填，意图识别时默认限定当前机器人下的场景，除非租户设置开启了多机器人意图识别\r\n\r\n  \"botId\": \"1\",\r\n\r\n  // 机器人 ID 列表，用于限定意图识别的范围，仅在租户设置开启了多机器人意图识别时生效\r\n\r\n  \"botIds\": [],\r\n\r\n  // 客户端 ID，可选，格式为 uuid，用于调用方主动中断请求（需要调用 /bote/chat/cancel 接口）\r\n\r\n  \"clientId\": \"xxx\",\r\n\r\n  // 会话 ID，可选，为空或 -1 时不记录会话消息\r\n\r\n  \"sessionId\": \"1\",\r\n\r\n  // 当前上下文 ID, 可选。上下文与场景绑定，用户在聊天窗口中每切换一次场景都会产生新的上下文\r\n\r\n  \"contextId\": \"\",\r\n\r\n  // 当前场景 ID。-1 表示用户手动退出当前场景；指定了场景 ID 但消息内容、文件列表都为空表示用户手动进入场景\r\n\r\n  \"sceneId\": \"1\",\r\n\r\n  // 当前场景名称\r\n\r\n  \"sceneName\": \"测试\",\r\n\r\n  // 上一个场景 ID, 退出场景时使用\r\n\r\n  \"lastSceneId\": \"\",\r\n\r\n  // 上一个上下文 ID, 退出场景时使用\r\n\r\n  \"lastContextId\": \"\",\r\n\r\n  // 消息\r\n\r\n  \"message\": {\r\n\r\n    // 消息类型，input: 用户输入，point: 副驾指令。默认为 input\r\n\r\n    \"type\": \"input\",\r\n\r\n    // 消息角色(user: 用户输入, tool: 页面交互)。默认为 user\r\n\r\n    \"role\": \"user\",\r\n\r\n    // 消息内容，用作系统变量中的用户查询($.system.query)。未指定 sceneId 或者开启了场景跳变时也会用于意图识别\r\n\r\n    \"content\": \"你好\",\r\n\r\n    // 文件 ID 列表\r\n\r\n    \"fileIds\": [],\r\n\r\n    // 参数（指令表单数据、副驾指令参数），绑定到场景入参（如果场景未配置入参，则会忽略）\r\n\r\n    \"params\": {},\r\n\r\n    // 关联消息 ID，可选，用户操作页面产生的消息需要传页面消息的 ID\r\n\r\n    \"refId\": null,\r\n\r\n    // 工具调用 ID, 仅简单场景中页面、页面函数回调使用，用于将回调结果作为大模型的工具调用结果\r\n\r\n    \"toolCallId\": null\r\n\r\n  },\r\n\r\n  // 上下文参数，结构需要与租户功能设置中配置的对话上下文一致，绑定到场景/工作流中的上下文参数\r\n\r\n  \"contextParams\": {}\r\n\r\n}\r\n\r\n```\r\n\r\n\r\n\r\n## 接口出参\r\n\r\n\r\n\r\n只支持流式输出，使用 Server-Sent Events 技术实现，响应头中会返回 `Content-Type: text/event-stream`。\r\n\r\n\r\n\r\n流式输出的格式与大模型的会话补全接口不同，请勿直接套用大模型的流式接口处理逻辑。\r\n\r\n\r\n\r\n服务器发送的每个事件可能包含以下属性:\r\n\r\n\r\n\r\n* id: 事件 ID, 我们用来表示消息 ID（整数）。如果 id 跟上一个事件相同，表示是同一条回复（工作流中的相同节点产生），回复内容需要拼起来，否则就表示是一条新回复（工作流中的不同节点产生）\r\n\r\n  * 仅表示回复的事件会返回，即 text, references, questions, page, pageFunc\r\n\r\n* event: 事件名称，用于区分用途\r\n\r\n  * `contextId`: 用于返回上下文 ID，事件数据为纯文本的 uuid（非 JSON 格式）\r\n\r\n  * `scene`: 用于返回意图识别的场景信息，事件数据为场景信息的 JSON 字符串形式，包含 sceneId, sceneName 两个属性\r\n\r\n  * `selectScene`: 意图识别未能识别到场景时返回，用于返回多个场景供用户手动选择，事件数据为推荐信息的 JSON 字符串形式，包含 content, scenes 两个属性，content 表示提示信息，scenes 表示场景列表\r\n\r\n  * `error`: 错误信息（执行失败，或其它系统错误），事件数据为错误信息（字符串）的 JSON 字符串形式\r\n\r\n  * `exception`: 异常堆栈，执行失败时返回\r\n\r\n  * `ready`: 表示已进入场景，没有回复。事件数据固定为纯文本 `[READY]`(非 JSON 格式)。两种情况: 1. 用户手动切换到场景; 2. 场景执行结束但没有产生任何回复\r\n\r\n  * `exitScene`: 表示退出当前场景，事件数据固定为纯文本 `[EXIT]`(非 JSON 格式)。两种情况: 1. 用户手动退出场景; 2. 场景或场景调用的对话型工作流里执行到了场景结束节点\r\n\r\n  * `done`: 表示响应结束，事件数据固定为纯文本 `[DONE]`(非 JSON 格式)\r\n\r\n    * 不论执行是否成功，结束时都会发送 `done` 事件\r\n\r\n  * `text`: 文本回复，事件数据为文本片段的 JSON 字符串形式（SSE 的响应格式不允许文本内有换行符，因此使用 JSON 形式做个转义）\r\n\r\n  * `references`: 参考文档，只在工作流中的知识问答节点开启了参考文档时返回，事件数据为参考文档列表的 JSON 字符串形式\r\n\r\n  * `questions`: 追问问题，只在工作流中的知识问答节点开启了追问时返回，事件数据为追问问题列表的 JSON 字符串形式\r\n\r\n  * `page`: 页面，事件数据为页面配置的 JSON 字符串形式\r\n\r\n  * `pageFunc`: 页面函数，事件数据为页面函数配置的 JSON 字符串形式\r\n\r\n* data: 事件数据，具体内容、结构跟事件名称相关\r\n\r\n\r\n\r\n注意:\r\n\r\n\r\n\r\n* 只有 `text` 事件有流式输出的效果（对同一个回复 ID 可能会发送一次或多次事件），其它事件都是一次性返回完整数据（同一个回复 ID 只会发送一次）\r\n\r\n\r\n\r\n正常情况下返回文本回复时的事件顺序: `contextId` -> `scene` -> `text`(多次) -> `done`\r\n\r\n\r\n\r\n示例(返回 3 条文本回复，中间那条有流式输出效果):\r\n\r\n```\r\n\r\nContent-Type: text/event-stream\r\n\r\nTransfer-Encoding: chunked\r\n\r\n\r\n\r\nevent:contextId\r\n\r\ndata:c9977ecf-d4ed-4a3e-aa10-305a7b7f740b\r\n\r\n\r\n\r\nevent:scene\r\n\r\ndata:{\"sceneName\":\"多回复测试\",\"sceneId\":\"1215305791857074176\"}\r\n\r\n\r\n\r\nid:1216997928345038848\r\n\r\nevent:text\r\n\r\ndata:\"调用大模型开始\"\r\n\r\n\r\n\r\nid:1216997928357621760\r\n\r\nevent:text\r\n\r\ndata:\"中国的\"\r\n\r\n\r\n\r\nid:1216997928357621760\r\n\r\nevent:text\r\n\r\ndata:\"的\"\r\n\r\n\r\n\r\nid:1216997928357621760\r\n\r\nevent:text\r\n\r\ndata:\"首都\"\r\n\r\n\r\n\r\nid:1216997928357621760\r\n\r\nevent:text\r\n\r\ndata:\"是\"\r\n\r\n\r\n\r\nid:1216997928357621760\r\n\r\nevent:text\r\n\r\ndata:\"北京\"\r\n\r\n\r\n\r\nid:1216997940328165376\r\n\r\nevent:text\r\n\r\ndata:\"调用大模型结束\"\r\n\r\n\r\n\r\nevent:done\r\n\r\ndata:[DONE]\r\n\r\n```','T'),(1002,'停止对话','停止进行中的对话','/bote/chat/cancel','GET',NULL,'{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"客户端ID\",\"name\":\"clientId\",\"type\":\"string\",\"require\":true,\"value\":\"\",\"key\":\"076a3bb2-4014-4ce9-a1b7-a426089f86e2\",\"parentKey\":-1}]}',NULL,'{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"响应编码\",\"name\":\"resultCode\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"64ff2441-aac6-436b-be6e-4d771d5d5b60\",\"parentKey\":-1},{\"description\":\"响应消息\",\"name\":\"resultMsg\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"3eaea294-e311-4c09-b94e-507e590b3a1e\",\"parentKey\":-1}]}','{\r\n  \"input\": \"curl --location \'http://10.10.176.135:9500/bote/api/bote/chat/completions?clientId=a9f6f479-0553-463a-978a-f763f32eba26\' \\\\\\n--header \'Content-Type: application/json\' \\\\\\n--header \'Authorization: Bearer abcd***1234\'\",\r\n  \"output\": \"{\\n  \\\"resultCode\\\": \\\"0\\\",\\n  \\\"resultMsg\\\": \\\"success\\\"\\n}\"\r\n}',2001,'2025-02-26 18:14:50','00A','2025-02-26 18:14:50',1,1,NULL,'{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"Cookie 请求头\",\"name\":\"Cookie\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"axef8ad2a-csa1-48a8-bss1-ba5155acg4da\",\"parentKey\":-1},{\"description\":\"API 密钥, 值为 \\\"Bearer 密钥\\\"\",\"name\":\"Authorization\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"245e2b31-bff6-2c1a-ec7c-3cf340480a98\",\"parentKey\":-1}]}','用于主动中断对话，业务系统可以直接调用\r\n\r\n\r\n\r\n## 接口鉴权\r\n\r\n两种方式:\r\n\r\n\r\n\r\n* 使用 session 鉴权: 传递 `Cookie` 请求头，里面要包含 session 的 cookie（一般名为 `BOTE_SESSION`）\r\n\r\n  * 适用于从业务系统前端触发的调用，此时业务系统后端可以从请求中获取到 cookie, 然后转发给博特平台后端\r\n\r\n  * 博特平台不同环境使用的 session cookie 名称不同，为方便兼容所有环境，建议直接透传所有 cookie\r\n\r\n  * 示例: `Cookie: BOTE_SESSION=xxx`\r\n\r\n* API 密钥: 传递 `Authorization` 请求头，值为 \"Bearer 密钥\"\r\n\r\n  * 密钥在平台的【设置 - API 开放 - 鉴权】中申请\r\n\r\n  * 不依赖业务系统前端的 cookie, 适用于业务系统后端异步或者在定时任务中调用\r\n\r\n  * 示例: `Authorization: Bearer xxx`\r\n\r\n\r\n\r\n## 接口地址\r\n\r\n\r\n\r\n* 请求方法: GET\r\n\r\n* 请求地址: `/api/bote/chat/cancel（前面加上环境地址，比如生产环境完整地址为 `http://10.10.176.135:9500/bote/api/bote/chat/cancel`）\r\n\r\n\r\n\r\n## 接口入参\r\n\r\n```json\r\n\r\n// 客户端ID\r\n\r\nclientId\r\n\r\n```\r\n\r\n\r\n\r\n## 接口出参\r\n\r\n```json\r\n\r\n{\r\n\r\n    // 响应编码，0 为成功，其它都表示失败\r\n\r\n    \"resultCode\": \"0\",\r\n\r\n    // 响应描述\r\n\r\n    \"resultMsg\": \"success\"\r\n\r\n}\r\n\r\n```','F'),(1003,'BoteClaw 对话','发起一次 BoteClaw 对话','/bote/chat/completions','POST',NULL,NULL,'{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"当前空间ID\",\"name\":\"spaceId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"adcb3439-2fde-4e56-b9d7-9fa27f5de345\",\"parentKey\":-1},{\"description\":\"应用对应的空间ID\",\"name\":\"tenantId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"adcb3439-2fde-4e56-b9d7-9fa27f5deb67\",\"parentKey\":-1},{\"description\":\"应用ID，默认-1\",\"name\":\"botId\",\"type\":\"integer\",\"require\":true,\"value\":\"\",\"key\":\"fc440006-34fa-4713-88bc-645febe57d40\",\"parentKey\":-1},{\"description\":\"客户端 ID，可选\",\"name\":\"clientId\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"e8c2024a-11a9-81d8-0d42-ba67ad65731b\",\"parentKey\":-1},{\"description\":\"会话 ID\",\"name\":\"sessionId\",\"type\":\"integer\",\"require\":false,\"value\":\"\",\"key\":\"52309665-aa68-7cd5-bf62-edf0c4d8c706\",\"parentKey\":-1},{\"description\":\"消息\",\"name\":\"message\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"fea2186e-365f-43eb-9d97-d8a42b755425\",\"parentKey\":-1,\"children\":[{\"description\":\"消息类型\",\"name\":\"type\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"8578933e-2004-c7a3-dd96-36b26cecc589\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"},{\"description\":\"消息角色\",\"name\":\"role\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"8d2c9f97-150e-b260-6b9f-01b03322975b\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"},{\"description\":\"消息内容\",\"name\":\"content\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"5b26ea1c-1410-bb11-91ff-52c31a92c928\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"},{\"description\":\"文件 ID 列表\",\"name\":\"fileIds\",\"type\":\"array\",\"require\":false,\"value\":\"\",\"key\":\"77d3b639-5071-5c49-f006-5f63e872b2d8\",\"parentKey\":\"fea2186e-365f-43eb-9d97-d8a42b755425\"}]}]}','{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"事件ID\",\"name\":\"id\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"adcb3439-2fde-4e56-b9d7-9fa27f5deb67\",\"parentKey\":-1},{\"description\":\"事件名称\",\"name\":\"envent\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"fc440006-34fa-4713-88bc-645febe57d40\",\"parentKey\":-1},{\"description\":\"事件数据\",\"name\":\"data\",\"type\":\"any\",\"require\":false,\"value\":\"\",\"key\":\"fea2186e-365f-43eb-9d97-d8a42b755425\",\"parentKey\":-1}]}','{\r\n  \"input\": \"curl --location --request POST \'http://10.10.176.135:9500/bote/api/bote/chat/completions\' \\\\\\n--header \'Authorization: Bearer abcd***1234\' \\\\\\n--header \'Content-Type: application/json\' \\\\\\n--header \'Accept: */*\' \\\\\\n--header \'Connection: keep-alive\' \\\\\\n--data-raw \'{\\n    \\\"botId\\\": \\\"-1\\\",\\n    \\\"tenantId\\\": \\\"0\\\",\\n    \\\"spaceId\\\": \\\"0\\\",\\n    \\\"sessionId\\\": \\\"1355102195176443904\\\",\\n    \\\"message\\\": {\\n        \\\"role\\\": \\\"user\\\",\\n        \\\"content\\\": \\\"输出当前时间\\\",\\n        \\\"type\\\": \\\"input\\\"\\n    },\\n    \\\"clientId\\\": \\\"a46997d4-4af9-4494-828f-d8c65e4b0fff\\\"\\n}\'\",\r\n  \"output\": \"Content-Type: text/event-stream\\nTransfer-Encoding: chunked\\n\\nid:1774687977332\\nevent:toolCall\\ndata:{\\\"toolCallId\\\":\\\"call_c755ec64631d44819196af\\\",\\\"toolName\\\":\\\"get_current_time\\\",\\\"input\\\":{}}\\n\\nid:1774687977332\\nevent:toolCallResult\\ndata:{\\\"toolCallId\\\":\\\"call_c755ec64631d44819196af\\\",\\\"toolName\\\":\\\"get_current_time\\\",\\\"output\\\":\\\"2026-03-28T16:53:06+0800\\\",\\\"success\\\":true,\\\"spentTime\\\":\\\"6\\\"}\\n\\nid:1774687977332\\nevent:text\\ndata:\\\"当前时间是 2026年3月28日 16:53:06 (东八区时间)。\\\"\\n\\nid:1774687977332\\nevent:done\\ndata:[DONE]\"\r\n}',2001,'2026-03-28 16:24:14','00A','2026-03-28 16:24:14',1,1,NULL,'{\r\n	\"key\": -1,\r\n	\"description\": \"根节点\",\r\n	\"name\": \"root\",\r\n	\"type\": \"object\",\r\n	\"require\": false,\r\n	\"value\": \"\",\r\n	\"children\": [\r\n		{\r\n			\"description\": \"Cookie 请求头\",\r\n			\"name\": \"Cookie\",\r\n			\"type\": \"string\",\r\n			\"require\": false,\r\n			\"value\": \"\",\r\n			\"key\": \"axef8ad2a-csa1-48a8-bss1-ba5155acg4da\",\r\n			\"parentKey\": -1\r\n		},\r\n		{\r\n			\"description\": \"API 密钥, 值为 \\\"Bearer 密钥\\\"\",\r\n			\"name\": \"Authorization\",\r\n			\"type\": \"string\",\r\n			\"require\": false,\r\n			\"value\": \"\",\r\n			\"key\": \"245e2b31-bff6-2c1a-ec7c-3cf340480a98\",\r\n			\"parentKey\": -1\r\n		}\r\n	]\r\n}','对话接口用于聊天窗口与后端的交互，主要用于博特平台前端，如果业务系统需要使用自己的聊天窗口，也可通过此接口与博特平台后端交付。\r\n\r\n## 接口鉴权\r\n两种方式:\r\n\r\n* 使用 session 鉴权: 传递 `Cookie` 请求头，里面要包含 session 的 cookie（一般名为 `BOTE_SESSION`）\r\n  * 适用于从业务系统前端触发的调用，此时业务系统后端可以从请求中获取到 cookie, 然后转发给博特平台后端\r\n  * 博特平台不同环境使用的 session cookie 名称不同，为方便兼容所有环境，建议直接透传所有 cookie\r\n  * 示例: `Cookie: BOTE_SESSION=xxx`\r\n* API 密钥: 传递 `Authorization` 请求头，值为 \"Bearer 密钥\"\r\n  * 密钥在平台的【设置 - API 开放 - 鉴权】中申请\r\n  * 不依赖业务系统前端的 cookie, 适用于业务系统后端异步或者在定时任务中调用\r\n  * 示例: `Authorization: Bearer xxx`\r\n\r\n## 接口地址\r\n\r\n* 请求方法: POST\r\n* 请求地址: `/api/bote/chat/completions`（前面加上环境地址，比如生产环境完整地址为 `http://10.10.176.135:9500/bote/api/bote/chat/completions`）\r\n\r\n## 接口入参\r\n```json\r\n{\r\n	\"botId\": \"-1\",\r\n	\"tenantId\": \"0\",\r\n	\"spaceId\": \"0\",\r\n	\"sessionId\": \"1355102195176443904\",\r\n	\"message\": {\r\n		\"role\": \"user\",\r\n		\"content\": \"输出当前时间\",\r\n		\"type\": \"input\"\r\n	},\r\n	\"clientId\": \"a46997d4-4af9-4494-828f-d8c65e4b0fff\"\r\n}\r\n```\r\n\r\n## 接口出参\r\n\r\n只支持流式输出，使用 Server-Sent Events 技术实现，响应头中会返回 `Content-Type: text/event-stream`。\r\n\r\n流式输出的格式与大模型的会话补全接口不同，请勿直接套用大模型的流式接口处理逻辑。\r\n\r\n服务器发送的每个事件可能包含以下属性:\r\n\r\n* id: 事件 ID, 我们用来表示消息 ID（整数）。如果 id 跟上一个事件相同，表示是同一条回复（工作流中的相同节点产生），回复内容需要拼起来，否则就表示是一条新回复（工作流中的不同节点产生）\r\n  * 仅表示回复的事件会返回，即 text, references, questions, page, pageFunc\r\n* event: 事件名称，用于区分用途\r\n  * `toolCall`: 用于记录触发的工具\r\n  * `toolCallResult`: 用于记录工具的输出\r\n  * `error`: 错误信息（执行失败，或其它系统错误），事件数据为错误信息（字符串）的 JSON 字符串形式\r\n  * `exception`: 异常堆栈，执行失败时返回\r\n  * `done`: 表示响应结束，事件数据固定为纯文本 `[DONE]`(非 JSON 格式)\r\n    * 不论执行是否成功，结束时都会发送 `done` 事件\r\n  * `text`: 文本回复，事件数据为文本片段的 JSON 字符串形式（SSE 的响应格式不允许文本内有换行符，因此使用 JSON 形式做个转义）\r\n* data: 事件数据，具体内容、结构跟事件名称相关\r\n\r\n注意:\r\n\r\n* 只有 `text` 事件有流式输出的效果（对同一个回复 ID 可能会发送一次或多次事件），其它事件都是一次性返回完整数据（同一个回复 ID 只会发送一次）\r\n\r\n正常情况下返回文本回复时的事件顺序: `text`(多次) -> `done`\r\n\r\n示例(返回 3 条文本回复，中间那条有流式输出效果):\r\n```\r\nContent-Type: text/event-stream\r\nTransfer-Encoding: chunked\r\n\r\nid:1774687977332\r\nevent:toolCall\r\ndata:{\"toolCallId\":\"call_c755ec64631d44819196af\",\"toolName\":\"get_current_time\",\"input\":{}}\r\n\r\nid:1774687977332\r\nevent:toolCallResult\r\ndata:{\"toolCallId\":\"call_c755ec64631d44819196af\",\"toolName\":\"get_current_time\",\"output\":\"2026-03-28T16:53:06+0800\",\"success\":true,\"spentTime\":\"6\"}\r\n\r\nid:1774687977332\r\nevent:text\r\ndata:\"当前时间是 2026年3月28日 16:53:06 (东八区时间)。\"\r\n\r\nid:1774687977332\r\nevent:done\r\ndata:[DONE]\r\n```','T'),(2001,'执行任务型工作流','执行指定工作流ID','/bote/flow/execute','POST',NULL,NULL,'{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"租户 ID(可选，也可通过请求头或 URL 参数传递)\",\"name\":\"tenantId\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"91260fc5-75e7-4b0c-adec-62efdcfe2f02\",\"parentKey\":-1,\"parentKeyPath\":[-1]},{\"description\":\"工作流ID\",\"name\":\"flowId\",\"type\":\"integer\",\"require\":true,\"value\":\"\",\"key\":\"fcf97dda-c191-4958-bbf1-b131b5a844bd\",\"parentKey\":-1,\"parentKeyPath\":[-1]},{\"description\":\"工作流入参\",\"name\":\"params\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"90a7ba57-4390-4a83-a777-f6f0a19cdc5d\",\"parentKey\":-1,\"parentKeyPath\":[-1]}],\"parentKeyPath\":[]}','{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"响应编码\",\"name\":\"resultCode\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"adcb3439-2fde-4e56-b9d7-9fa27f5deb67\",\"parentKey\":-1},{\"description\":\"响应消息\",\"name\":\"resultMsg\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"fc440006-34fa-4713-88bc-645febe57d40\",\"parentKey\":-1},{\"description\":\"返回对象, 与工作流出参一致\",\"name\":\"resultObject\",\"type\":\"any\",\"require\":false,\"value\":\"\",\"key\":\"fea2186e-365f-43eb-9d97-d8a42b755425\",\"parentKey\":-1}]}','{\r\n  \"input\": \"curl --location --request POST \'http:\\/\\/10.10.176.135:9500\\/bote\\/api\\/bote\\/flow\\/execute\' \\\\\\r\\n--header \'Authorization: Bearer abcd***1234\' \\\\\\r\\n--header \'Content-Type: application\\/json\' \\\\\\r\\n--header \'Accept: *\\/*\' \\\\\\r\\n--header \'Connection: keep-alive\' \\\\\\r\\n--data-raw \'{\\r\\n    \\\"flowId\\\": \\\"1184029820491132928\\\",\\r\\n\\t  \\\"params\\\": {\\r\\n\\t\\t  \\\"code\\\": \\\"***\\\",\\r\\n\\t\\t  \\\"name\\\": \\\"张三\\\"\\r\\n\\t  }\\r\\n}\'\",\r\n  \"output\": \"{\\r\\n  \\\"resultCode\\\": \\\"0\\\",\\r\\n  \\\"resultMsg\\\": \\\"success\\\",\\r\\n  \\\"resultObject\\\": {\\r\\n    \\\"id\\\": 123456,\\r\\n    \\\"name\\\": \\\"张三\\\",\\r\\n    \\\"phone\\\": \\\"188***11\\\"\\r\\n  }\\r\\n}\"\r\n}',2002,'2025-02-26 18:14:51','00A','2025-02-26 18:14:51',1,1,NULL,NULL,'工作流开放单独的执行接口，业务系统可以直接调用。\r\n\r\n\r\n\r\n## 接口鉴权\r\n\r\n两种方式:\r\n\r\n\r\n\r\n* 使用 session 鉴权: 传递 `Cookie` 请求头，里面要包含 session 的 cookie（一般名为 `BOTE_SESSION`）\r\n\r\n  * 适用于从业务系统前端触发的调用，此时业务系统后端可以从请求中获取到 cookie, 然后转发给博特平台后端\r\n\r\n  * 博特平台不同环境使用的 session cookie 名称不同，为方便兼容所有环境，建议直接透传所有 cookie\r\n\r\n  * 示例: `Cookie: BOTE_SESSION=xxx`\r\n\r\n* API 密钥: 传递 `Authorization` 请求头，值为 \"Bearer 密钥\"\r\n\r\n  * 密钥在平台的【设置 - API 开放 - 鉴权】中申请\r\n\r\n  * 不依赖业务系统前端的 cookie, 适用于业务系统后端异步或者在定时任务中调用\r\n\r\n  * 示例: `Authorization: Bearer xxx`\r\n\r\n\r\n\r\n## 接口地址\r\n\r\n\r\n\r\n* 请求方法: POST\r\n\r\n* 请求地址: `/api/bote/flow/execute`（前面加上环境地址，比如生产环境完整地址为 `http://10.10.176.135:9500/bote/api/bote/flow/execute`）\r\n\r\n\r\n\r\n## 接口入参\r\n\r\n```json\r\n\r\n{\r\n\r\n  // 租户 ID，可选，也可通过请求头 Tenant-Id 或 URL 参数 tenantId 传递。使用 API 密钥鉴权方式时可不传（API 密钥与租户是绑定的，系统能自动查出来）\r\n\r\n  \"tenantId\": 0,\r\n\r\n  // 工作流 ID\r\n\r\n  \"flowId\": 1,\r\n\r\n  // 工作流入参，结构需要与工作流的入参配置一致\r\n\r\n  \"params\": {},\r\n\r\n}\r\n\r\n```\r\n\r\n\r\n\r\n## 接口出参\r\n\r\n```json\r\n\r\n{\r\n\r\n    // 响应编码，0 为成功，其它都表示失败\r\n\r\n    \"resultCode\": \"0\",\r\n\r\n    // 响应描述\r\n\r\n    \"resultMsg\": \"success\",\r\n\r\n    // 响应对象，即工作流的出参（结构与工作流的出参配置一致）\r\n\r\n    \"resultObject\": {}\r\n\r\n}\r\n\r\n```','F'),(2002,'执行API技能','执行指定API技能','/bote/api/execute','POST',NULL,NULL,'{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"服务 ID\",\"name\":\"serviceId\",\"type\":\"integer\",\"require\":true,\"value\":\"\",\"key\":\"2eb6507f-0ff5-4409-b5fc-284477ee1f02\",\"parentKey\":-1},{\"description\":\"params\",\"name\":\"params\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"1af73607-10c2-4d73-9afe-28469c9dfcb0\",\"parentKey\":-1,\"children\":[{\"description\":\"path 参数\",\"name\":\"path\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"ec66addc-e47e-4bcb-a28a-d13d37304ed3\",\"parentKey\":\"1af73607-10c2-4d73-9afe-28469c9dfcb0\"},{\"description\":\"头部参数\",\"name\":\"header\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"8b397511-c8ac-4889-906f-55570301aa2a\",\"parentKey\":\"1af73607-10c2-4d73-9afe-28469c9dfcb0\"},{\"description\":\"query 参数\",\"name\":\"query\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"key\":\"dc04a875-36a4-457e-bc8c-75a184bf64d6\",\"parentKey\":\"1af73607-10c2-4d73-9afe-28469c9dfcb0\"},{\"description\":\"body 参数\",\"name\":\"body\",\"type\":\"any\",\"require\":false,\"value\":\"\",\"key\":\"7d08cfdc-a9dc-4019-a11e-b6613040671a\",\"parentKey\":\"1af73607-10c2-4d73-9afe-28469c9dfcb0\"}]}]}','{\"key\":-1,\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"require\":false,\"value\":\"\",\"children\":[{\"description\":\"响应编码\",\"name\":\"resultCode\",\"type\":\"string\",\"require\":false,\"value\":\"\",\"key\":\"adcb3439-2fde-4e