INSERT INTO `bt_bot_scene_prompt` VALUES (1216268010323439616,1216267928341573632,100,NULL,'根据参考信息回答我的问题或指示。\r\n\r\n遵循以下规则:\r\n\r\n1. 确保你的回复忠实于参考文献，简洁但不丢失信息，不要捏造信息\r\n2. 如果参考信息与问题无关，只需回复不知道或没有查询到相关信息，不要用你的原始知识来回答问题\r\n3. 回复使用 markdown 格式\r\n\r\n---------------------\r\n我的问题或指示: {question}\r\n---------------------\r\n参考信息: {context}','2025-03-26 18:02:05','00A','2025-03-26 18:02:05',1000,1000,NULL,'scene',1,NULL);
