--
-- Table structure for table `bt_chat_message`
--


CREATE TABLE `bt_chat_message` (
  `message_id` bigint(20) NOT NULL COMMENT '消息 ID',
  `scene_id` bigint(20) NOT NULL COMMENT '场景 ID',
  `conversation_id` bigint(20) NOT NULL COMMENT '会话 ID',
  `context_id` varchar(40) NOT NULL COMMENT '上下文 ID',
  `seq` int(11) NOT NULL COMMENT '消息顺序',
  `message_role` varchar(18) NOT NULL COMMENT ' 消息角色',
  `message_content` longtext COMMENT '消息内容',
  `tool_call_id` text COMMENT ' 工具调用标识',
  `tool_name` text COMMENT '工具名称',
  `tool_arguments` longtext COMMENT '工具参数(JSON)',
  `user_id` bigint(20) DEFAULT NULL COMMENT '用户 ID',
  `create_time` datetime DEFAULT NULL COMMENT '提交时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`message_id`),
  KEY `idx_bt_chat_msg_seq` (`context_id`,`seq`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='场景会话消息';
/*!40101 SET character_set_client = @saved_cs_client */;

