--
-- Table structure for table `bt_chat_scene_process`
--


CREATE TABLE `bt_chat_scene_process` (
  `id` bigint(20) NOT NULL COMMENT '会话场景进度 ID',
  `session_id` bigint(20) DEFAULT NULL COMMENT '会话 ID',
  `scene_id` bigint(20) DEFAULT NULL COMMENT '场景 ID',
  `context_id` varchar(40) DEFAULT NULL COMMENT '上下文 ID',
  `chat_status` varchar(4) DEFAULT NULL COMMENT '对话状态(1: 运行中, 2: 已完成)',
  `created_time` datetime NOT NULL,
  `status_cd` varchar(4) NOT NULL,
  `updated_time` datetime DEFAULT NULL,
  `creator_id` bigint(20) DEFAULT NULL,
  `updator_id` bigint(20) DEFAULT NULL,
  `remark` varchar(200) DEFAULT NULL,
  `scene_name` varchar(50) DEFAULT NULL COMMENT '场景名称',
  `tenant_id` bigint(20) DEFAULT NULL COMMENT '租户 ID',
  `bot_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_bt_chat_process_session` (`session_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会话场景进度';
/*!40101 SET character_set_client = @saved_cs_client */;

