CREATE TABLE `bt_dataset` (
  `id` bigint(20) NOT NULL COMMENT '数据集ID',
  `app_id` int(11) NOT NULL COMMENT '应用ID',
  `space_id` bigint(20) NOT NULL COMMENT '工作空间ID',
  `schema_id` bigint(20) NOT NULL COMMENT 'Schema ID',
  `name` varchar(255) NOT NULL COMMENT '数据集名称',
  `description` varchar(2048) DEFAULT NULL COMMENT '数据集描述',
  `category` varchar(64) NOT NULL COMMENT '业务场景分类',
  `biz_category` varchar(128) NOT NULL COMMENT '业务场景下自定义分类',
