--
-- Table structure for table `bt_dc_doc_content`
--


CREATE TABLE `bt_dc_doc_content` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `document_id` varchar(64) NOT NULL COMMENT '文档唯一标识',
  `content` text COMMENT '文档内容json',
  `ydoc` text COMMENT '文档yjs格式二进制内容base64',
  `text_content` text COMMENT '文档文本内容',
  `creator_id` bigint(20) NOT NULL COMMENT '创建人ID',
  `updator_id` bigint(20) DEFAULT NULL COMMENT '修改人ID',
  `created_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `status_cd` varchar(10) DEFAULT '00A' COMMENT '状态：00A-正常，00X-删除',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`,`tenant_id`),
  KEY `idx_doc_id_content` (`document_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='在线文本文档内容表';
/*!40101 SET character_set_client = @saved_cs_client */;

