  `granted_by` bigint(20) NOT NULL COMMENT '授权人ID',
  `expires_at` timestamp NULL DEFAULT NULL COMMENT '权限过期时间',
  `creator_id` bigint(20) NOT NULL COMMENT '创建人ID',
  `updator_id` bigint(20) NOT NULL COMMENT '更新人ID',
  `created_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT NULL COMMENT '更新时间',
  `tenant_id` bigint(20) DEFAULT NULL COMMENT '租户ID',
  `status_cd` varchar(10) NOT NULL DEFAULT '00A' COMMENT '状态：00A-正常，00X-删除',
  PRIMARY KEY (`permission_id`),
  KEY `idx_subject_type_id` (`subject_type`,`subject_id`),
  KEY `idx_permission_type` (`permission_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='文档库权限表';
