--
-- Table structure for table `bt_experiment`
--


CREATE TABLE `bt_experiment` (
  `id` bigint(20) NOT NULL COMMENT '实验ID',
  `space_id` bigint(20) NOT NULL COMMENT '工作空间ID',
  `created_by` varchar(128) NOT NULL COMMENT '创建者',
  `name` varchar(255) NOT NULL COMMENT '实验名称',
  `description` varchar(1024) DEFAULT NULL COMMENT '实验描述',
  `eval_set_version_id` bigint(20) NOT NULL COMMENT '评测集版本ID',
  `target_type` bigint(20) NOT NULL COMMENT '评估对象类型',
  `target_version_id` bigint(20) NOT NULL COMMENT '评估对象版本ID',
  `eval_conf` longtext COMMENT '实验评估流程配置（JSON格式）',
  `status` int(11) NOT NULL COMMENT '状态',
  `status_message` longtext COMMENT '状态提示信息（JSON格式）',
  `start_at` datetime DEFAULT NULL COMMENT '开始执行时间',
  `end_at` datetime DEFAULT NULL COMMENT '结束执行时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted_at` bigint(20) NOT NULL COMMENT '删除时间（时间戳，0表示未删除）',
  `latest_run_id` bigint(20) DEFAULT NULL COMMENT '最后运行ID',
  `target_id` bigint(20) NOT NULL COMMENT '评估对象ID',
  `eval_set_id` bigint(20) NOT NULL COMMENT '评测集ID',
  `credit_cost` int(11) DEFAULT NULL COMMENT '权益消耗模式',
  `source_type` int(11) NOT NULL COMMENT '实验来源类型，评测:1,自动化任务:2',
  `source_id` varchar(128) DEFAULT NULL COMMENT '实验来源ID',
  `expt_type` int(11) NOT NULL COMMENT '实验类型，offline:1,online:2',
  `max_alive_time` bigint(20) DEFAULT NULL COMMENT '最大存活时间',
  `catalog_item_id` bigint(20) DEFAULT NULL COMMENT '目录 ID',
  PRIMARY KEY (`id`),
  KEY `idx_bt_experiment_space_id` (`space_id`),
  KEY `idx_bt_experiment_eval_set_id` (`eval_set_id`),
  KEY `idx_bt_experiment_target_id` (`target_id`),
  KEY `idx_bt_experiment_deleted_at` (`deleted_at`),
  KEY `idx_bt_experiment_status` (`status`),
  KEY `idx_bt_experiment_expt_type` (`expt_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='实验主表';
/*!40101 SET character_set_client = @saved_cs_client */;

