CREATE TABLE `bt_knowledge_base` (
  `knowledge_id` bigint(20) NOT NULL COMMENT '知识库 ID',
  `catalog_item_id` bigint(20) DEFAULT NULL COMMENT '目录 ID',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户 ID',
  `knowledge_name` varchar(255) DEFAULT NULL COMMENT '知识库名称',
  `knowledge_desc` longtext COMMENT '知识库描述',
  `knowledge_icon` longtext COMMENT '知识库图标',
  `file_counts` bigint(20) DEFAULT NULL COMMENT '文件数',
  `knowledge_status` varchar(4) DEFAULT NULL COMMENT '知识库状态(10A: 未发布, 10B: 发布中, 10C: 已修改, 10D: 已发布, 10E: 发布失败, 10X: 已删除)',
  `error_message` longtext COMMENT '报错信息',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `status_cd` varchar(4) DEFAULT NULL,
  `creator_id` bigint(20) DEFAULT NULL,
  `created_time` datetime DEFAULT NULL,
  `updator_id` bigint(20) DEFAULT NULL,
  `updated_time` datetime DEFAULT NULL,
  `knowledge_type` varchar(12) DEFAULT NULL COMMENT '知识库类型(rag, docChain)',
  `topic_id` bigint(20) DEFAULT NULL COMMENT 'DocChain 主题 ID',
  `knowledge_strategy` longtext COMMENT 'DocChain 策略',
  `is_exist` varchar(4) DEFAULT NULL COMMENT 'DocChain 知识库是否已存在',
  `is_temporary` char(1) DEFAULT NULL,
  `ext_config_json` text COMMENT '扩展配置(JSON 字符串)',
  `visibility_scope` varchar(20) DEFAULT 'PUBLIC' COMMENT '可见范围：PRIVATE-私有，PUBLIC-全员可见，MEMBERS-成员可见',
  `color` varchar(500) DEFAULT NULL COMMENT '知识库图标颜色',
  `kb_code` varchar(64) DEFAULT NULL COMMENT '知识库编码',
  `owner_id` bigint(20) DEFAULT NULL COMMENT '知识库所有者',
  `space_id` bigint(20) DEFAULT NULL COMMENT '空间id',
  PRIMARY KEY (`knowledge_id`,`tenant_id`),
  KEY `idx_kb_code` (`kb_code`),
  KEY `idx_knowledge_space_id` (`space_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='知识库';
/*!40101 SET character_set_client = @saved_cs_client */;

