--
-- Table structure for table `bt_library_large_model`
--


CREATE TABLE `bt_library_large_model` (
  `model_id` bigint(20) NOT NULL COMMENT '模型 ID',
  `model_code` varchar(128) DEFAULT NULL COMMENT '模型编码',
  `model_name` varchar(128) NOT NULL COMMENT '模型名称',
  `model_type` varchar(30) NOT NULL COMMENT '模型类型(llm: 大语言, embedding: 文本词嵌入, stt: 语音转文本, tts: 文本转语音, rerank: 排序)',
  `model_desc` varchar(255) DEFAULT NULL COMMENT '模型描述',
  `access_url` varchar(255) DEFAULT NULL COMMENT '访问地址',
  `access_key` varchar(255) DEFAULT NULL COMMENT '访问秘钥',
  `temperature` decimal(3,2) DEFAULT NULL COMMENT '温度系数',
  `max_tokens` int(11) DEFAULT NULL COMMENT '最大令牌数',
  `ext_attr_json` text COMMENT '扩展参数',
  `created_time` datetime NOT NULL,
  `status_cd` varchar(4) NOT NULL,
  `updated_time` datetime DEFAULT NULL,
  `creator_id` bigint(20) DEFAULT NULL,
  `updator_id` bigint(20) DEFAULT NULL,
  `remark` varchar(200) DEFAULT NULL,
  `tenant_id` bigint(20) NOT NULL,
  `product_type` varchar(100) DEFAULT NULL COMMENT '产品系列',
  `model_icon` longtext COMMENT '模型图标',
  `function_call_mode` varchar(20) DEFAULT NULL COMMENT '函数调用模式(none: 不支持, tool: Tool Call, function: Function Call)',
  `context_length` int(11) DEFAULT NULL COMMENT '上下文长度',
  `supports_vision` char(1) DEFAULT NULL,
  `is_public` char(1) DEFAULT NULL COMMENT '是否公共(T/F), 仅用于平台级模型, 非公共模型只供平台自身使用，对租户不可见',
  `protocol_type` varchar(20) DEFAULT NULL,
  `streaming_function_call` char(1) DEFAULT NULL COMMENT '是否支持流式函数调用(T/F)',
  `data_from` varchar(4) DEFAULT NULL COMMENT '来源：空为租户来源，10A为通用智能体来源，这个时候租户id存储的是空间id',
  `is_enabled` varchar(1) DEFAULT NULL COMMENT '是否启用',
  PRIMARY KEY (`model_id`,`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='模型';
/*!40101 SET character_set_client = @saved_cs_client */;

