--
-- Table structure for table `bt_plat_scene_info`
--


CREATE TABLE `bt_plat_scene_info` (
  `plat_scene_id` bigint(20) NOT NULL COMMENT '模板id',
  `scene_id` bigint(20) NOT NULL COMMENT '智能体id（关联bt_bot_scene表）',
  `sort_order` int(11) NOT NULL COMMENT '排序值',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户id',
  `catalog_item_id` bigint(20) NOT NULL COMMENT '模板分类',
  `status_cd` varchar(4) NOT NULL,
  `creator_id` bigint(20) DEFAULT NULL,
  `created_time` datetime DEFAULT NULL,
  `updator_id` bigint(20) DEFAULT NULL,
  `updated_time` datetime DEFAULT NULL,
  `remark` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`plat_scene_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='模板智能体表';
/*!40101 SET character_set_client = @saved_cs_client */;

