--
-- Table structure for table `bt_prompt`
--


CREATE TABLE `bt_prompt` (
  `prompt_id` bigint(20) NOT NULL COMMENT '提示词 ID',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户 ID',
  `catalog_item_id` bigint(20) DEFAULT NULL COMMENT '目录 ID',
  `prompt_content` longtext COMMENT '提示词内容',
  `prompt_title` varchar(100) DEFAULT NULL COMMENT '提示词标题',
  `created_time` datetime NOT NULL,
