--
-- Table structure for table `bt_skill_attr_value`
--


CREATE TABLE `bt_skill_attr_value` (
  `attr_value_id` bigint(20) NOT NULL COMMENT '属性值 ID',
  `attr_id` bigint(20) NOT NULL COMMENT '属性 ID',
  `attr_value_name` varchar(250) DEFAULT NULL COMMENT '属性值名称',
  `attr_value_desc` varchar(4000) DEFAULT NULL,
  `attr_value` text COMMENT '属性值',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户 ID',
  `sortby` bigint(20) DEFAULT NULL COMMENT '排序',
  `creator_id` bigint(20) DEFAULT NULL,
  `created_time` datetime DEFAULT NULL,
  `status_cd` varchar(10) DEFAULT NULL,
  `updator_id` bigint(20) DEFAULT NULL,
  `updated_time` datetime DEFAULT NULL,
  `remark` varchar(250) DEFAULT NULL,
  `attr_value_code` varchar(50) DEFAULT NULL COMMENT '属性值编码',
  `is_required` varchar(1) DEFAULT NULL COMMENT '是否必填',
  `comp_type` varchar(50) DEFAULT NULL COMMENT '属性渲染风格',
  PRIMARY KEY (`attr_value_id`,`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='静态属性值';
/*!40101 SET character_set_client = @saved_cs_client */;

