INSERT INTO `bt_skill_flow_node_cfg` VALUES (1,'root','根节点',NULL,'[{\"groupName\":\"基础\",\"groupCode\":\"logic\"},{\"groupName\":\"技能\",\"groupCode\":\"skill\"},{\"groupName\":\"循环\",\"groupCode\":\"loop\"},{\"groupName\":\"函数\",\"groupCode\":\"func\"},{\"groupName\":\"模型\",\"groupCode\":\"model\"},{\"groupName\":\"知识\",\"groupCode\":\"knowledge\"},{\"groupName\":\"Web 自动化\",\"groupCode\":\"webAutomation\"},{\"groupName\":\"数据\",\"groupCode\":\"datasource\"},{\"groupName\":\"意图\",\"groupCode\":\"intent\"}]',NULL,NULL,1,'T','2025-12-26 10:00:00','00A','2026-01-17 18:00:00',1,NULL,NULL),(2,'start','开始','logic','设置输入参数',NULL,NULL,1,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(3,'if','条件','logic','支持多条件判断，按条件执行分支，类似 代码的if-elseif-else；最后一个分支固定为 else，该分支不支持配置条件和删除',NULL,NULL,2,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(4,'parallel','并行','logic','同时启动所有分支，所有分支执行完毕后，才进入下一步',NULL,NULL,3,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(5,'reply','回复','logic','手动输入一段文本（支持\"/\"插入参数），返回给前端并结束流程，后面不能连接其他节点',NULL,'multiStep',4,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(6,'setVariable','变量','logic','对指定的变量进行赋值',NULL,NULL,5,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(7,'messagePush','指令','logic','根据配置的系统指令类型，执行相应操作',NULL,'multiStep',6,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(8,'end','结束','logic','结束',NULL,'oneStep',7,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(9,'end','智能体结束','logic','主要应用于任务型工作流中，执行完成并退出场景。数量不受限制，可根据需求在工作流中途灵活终止执行','null','multiStep',8,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(10,'service','API','skill','用于调用 API 技能，选择服务 → 填写入参 ，出参根据服务自动带出',NULL,NULL,1,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(11,'page','页面','skill','仅应用于主驾场景聊天窗口中弹出交互页面；用户在页面中录入信息并提交，重新触发流程，后面不能连接其他节点',NULL,'multiStep',2,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(12,'pageFunc','页面函数','skill','应用于副驾场景，向前端返回页面函数调；执行成功后工作流会停止执行，后面不能连接其它节点',NULL,'multiStep',3,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(13,'sql','SQL','skill','调用SQL类型的技能，完成对数据库的增删改查等操作',NULL,NULL,4,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(14,'workflow','流程','skill','用于调用其他已经封装好的任务型工作流',NULL,NULL,5,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(15,'plugin','插件','skill','用于调用已上架的插件能力，给入参赋值后即可使用，返回结果可被后续节点引用',NULL,NULL,6,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(16,'a2a','A2A 服务','skill','调用 A2A 服务',NULL,NULL,7,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(17,'loop','循环','loop','用于通过设定循环次数和逻辑，重复执行一系列任务',NULL,NULL,1,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(18,'loopStart','循环开始','loop','循环的开始节点',NULL,NULL,2,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(19,'break','跳出循环','loop','终止当前循环任务，跳转到循环外的下一节点',NULL,NULL,3,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(20,'continue','继续循环','loop','跳出当前循环任务，继续下一次循环',NULL,NULL,4,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(21,'toolbox','工具箱','func','用于调用系统内置的服务函数',NULL,NULL,1,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(22,'script','脚本','func','用于执行自定义脚本，支持Groovy 4.x、Python 3.x两种语言',NULL,NULL,2,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(23,'llm','大模型','model','用于调用大模型的会话功能补全，使用提示词生成回复。',NULL,NULL,1,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(24,'llmSkill','大模型服务','model','用于调用插件类型的技能（封装好的、可复用的大模型能力）',NULL,NULL,2,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(25,'agent','Agent','model','依照服务描述，自动规划并调用已注册至 MCP 的业务服务，即插即用',NULL,'multiStep',3,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(26,'mcpTool','MCP工具','model','从MCP服务中选择一个工具进行调用',NULL,NULL,4,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(27,'paramExtractor','参数提取','model','依托大模型，从任意自由文本中精准抽取所需参数',NULL,NULL,6,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(28,'agentSwitch','智能体切换','model','智能体各场景独立运行的基础上，构建跨智能应用-智能体场景处理的路由机制',NULL,'multiStep',7,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(29,'scene','智能体','model','智能体','null','null',8,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(30,'knowledgeChat','知识问答','knowledge','通过大模型对知识进行检索和总结',NULL,NULL,1,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(31,'knowledgeRetrieval','知识检索','knowledge','用于调用知识库的召回接口。支持引用参数',NULL,NULL,2,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(32,'insertRecord','新增记录','datasource','选择一张数据表，配置字段配置，即可新增记录',NULL,NULL,1,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(33,'updateRecords','更新记录','datasource','选择一张数据表，配置更新条件和更新字段，即可更新记录',NULL,NULL,2,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(34,'deleteRecords','删除记录','datasource','选择一张数据表，配置删除条件，即可删除记录',NULL,NULL,3,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(35,'querySingleRecord','查询单条','datasource','选择一张数据表，配置查询条件，即可查询单条记录',NULL,NULL,4,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(36,'queryRecords','查询多条','datasource','选择一张数据表，配置查询条件，即可查询多条记录',NULL,NULL,5,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(37,'slmRetrieval','微调模型','intent','调用训练过的模型精准识别意图',NULL,NULL,1,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(38,'questionClassifier','问题分类','model','用于对文本做分类，基于大模型实现。大模型基于语义自动归类，也可以配置指令告知大模型判定分类',NULL,NULL,5,'F','2025-12-26 10:00:00','00A','2025-12-26 10:00:00',1,NULL,NULL),(40,'playwright','PlayWright','webAutomation','使用 PlayWright 自动化操作 Chromium 浏览器，可实现网页爬取、UI 测试、流程自动化等',NULL,NULL,8,'F','2026-01-14 14:00:00','00A',NULL,NULL,NULL,NULL),(50,'agentSkill','Agent Skill','model','使用大模型和 Agent Skill 生成回复',NULL,NULL,3,'F','2026-02-02 12:00:00','00A',N