a.util.Collections\r\nimport java.util.stream.Collectors;\r\nimport org.apache.commons.collections4.CollectionUtils\r\nimport org.apache.commons.collections4.MapUtils\r\nimport org.apache.commons.lang3.StringUtils\r\nimport java.util.List\r\nimport java.util.Map\r\n  /**\r\n   * 将对象列表为map形式\r\n   *\r\n   * @param list 对象列表\r\n   * @param leftKey map 键\r\n   * @param rightKey map 键值\r\n   * @return: 转换结果\r\n   **/\r\ndef invoke(List<Object> list, String leftKey, String rightKey) {\r\n  if (CollectionUtils.isEmpty(list) || StringUtils.isEmpty(leftKey)) {\r\n    return [\'result\': Collections.emptyMap()]\r\n  }\r\n  List<Map<String, Object>> datas = JsonUtil.parseJson(JsonUtil.toJsonString(list), new TypeReference<List<Map<String, Object>>>() {\r\n  })\r\n  if (StringUtils.isEmpty(rightKey)){\r\n    return [\'result\': CollectionUtils.emptyIfNull(datas).stream().collect(\r\n      Collectors.toMap(p -> MapUtils.getObject(p, leftKey), p->p))]\r\n  }\r\n  return [\'result\': CollectionUtils.emptyIfNull(datas).stream().collect(\r\n    Collectors.toMap(p -> MapUtils.getObject(p, leftKey), p -> MapUtils.getObject(p, rightKey)))]\r\n}','{\"key\":\"-1\",\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"children\":[{\"description\":\"\",\"name\":\"list\",\"type\":\"array\",\"value\":\"\",\"key\":\"7c411490-24a8-4ab2-8d56-21b92747aae2\",\"parentKey\":\"-1\",\"parentKeyPath\":[\"-1\"],\"children\":null,\"parentType\":\"object\",\"defaultValue\":\"\",\"operation\":null},{\"description\":\"\",\"name\":\"leftKey\",\"type\":\"string\",\"value\":\"\",\"key\":\"fd5f2936-4ad6-449b-b4fa-8099c93ef3c5\",\"parentKey\":\"-1\",\"parentKeyPath\":[\"-1\"],\"children\":null,\"parentType\":\"object\",\"defaultValue\":\"\",\"operation\":null},{\"description\":\"\",\"name\":\"rightKey\",\"type\":\"string\",\"value\":\"\",\"key\":\"ec4cd3e5-53d1-440e-bfce-0a3b6e2a3f4a\",\"parentKey\":\"-1\",\"parentKeyPath\":[\"-1\"],\"parentType\":\"object\",\"defaultValue\":\"\",\"operation\":null}],\"parentKeyPath\":[]}','{\"key\":\"-1\",\"description\":\"根节点\",\"name\":\"root\",\"type\":\"object\",\"children\":[{\"description\":\"\",\"name\":\"result\",\"type\":\"object\",\"value\":\"\",\"key\":\"777b41e5-2509-4a32-90d9-16fac88bb23b\",\"parentKey\":\"-1\",\"parentKeyPath\":[\"-1\"],\"parentType\":\"object\",\"defaultValue\":\"\",\"operation\":null}],\"parentKeyPath\":[]}','2025-09-01 20:00:30','00A','2025-09-01 20:02:36',1000,1000,'返回MAP,指定两个字段的值做为MAP的一对键值对',-1,'Groovy',-1,NULL);
